-- CI/merge and observed deployed media hashes. Caller must set the batch gate.
DO $rollitos$
DECLARE
 j constant jsonb := $records$[{"id":"75a42c9e-6fe6-474f-8657-dde10e3f96c1","recipe_group_id":"f2371d66-d49e-4092-94d0-7e3e2584aa39","slug":"rollitos-de-anis","public_path":"/rollitos-de-anis","source_url":"https://manualdecocina.com/rollitos-de-anis/","language":"es","title":"Rollitos de anís verde al horno con naranja","excerpt":"Rollitos de anís verde con naranja y aceite, horneados por tandas: cantidades agrupadas, reposo, enfriado y nutrición estimada sin inventar datos ausentes.","summary":"Pequeños rollitos de anís verde horneados, con aceite de oliva y zumo de naranja, de textura de galleta. Fórmula original propuesta para 18 unidades, sin licor, huevo ni leche añadidos; 105 minutos completos con dos tandas y enfriado, pendientes de ensayo de cocina.","category":"Postres","category_slug":"postres","difficulty":"Fácil","course":"Galletas","cuisine":"Inspiración española","prep_time_minutes":25,"cook_time_minutes":40,"total_time_minutes":105,"servings":18,"ingredients":[{"name":"harina de trigo de uso común","amount":"300","unit":"g","group":"Masa"},{"name":"aceite de oliva","amount":"80","unit":"g","group":"Masa"},{"name":"zumo de naranja crudo, recién exprimido y sin semillas","amount":"100","unit":"g","group":"Masa"},{"name":"azúcar blanco granulado","amount":"70","unit":"g","group":"Masa"},{"name":"semillas alimentarias de anís verde (Pimpinella anisum)","amount":"4","unit":"g","group":"Aroma e impulsor"},{"name":"polvo de hornear de doble acción","amount":"6","unit":"g","group":"Aroma e impulsor"},{"name":"sal fina","amount":"1","unit":"g","group":"Aroma e impulsor"}],"steps":[{"title":"Prepara los ingredientes y las bandejas","content":"Prepara báscula, cuencos, mortero, espátula, cuchillo y dos bandejas de unos 30 × 40 cm con papel de horno, sin grasa adicional. Lava la naranja bajo agua corriente antes de cortarla y exprime; retira semillas y pesa 100 g de zumo. Pesa aparte 300 g de harina, 80 g de aceite, 70 g de azúcar, 4 g de anís verde, 6 g de polvo de hornear y 1 g de sal. Usa semillas alimentarias de anís verde, no anís estrellado, hinojo ni licor.","image_url":"/recetas/rollitos-de-anis/paso-01.webp","image_alt":"Rollitos de anís: Prepara los ingredientes y las bandejas"},{"title":"Machaca el anís y mezcla los secos","content":"Machaca brevemente los 4 g de anís en el mortero hasta romper las semillas, sin retirar ninguna parte. Mezcla en un cuenco los 300 g de harina, los 6 g de polvo de hornear y el 1 g de sal, repartiéndolos con una cuchara. Esta versión lleva impulsor químico y no levadura de panadería. No pruebes harina ni masa crudas aunque no lleven huevo.","image_url":"/recetas/rollitos-de-anis/paso-02.webp","image_alt":"Rollitos de anís: Machaca el anís y mezcla los secos"},{"title":"Mezcla el zumo, el aceite y el azúcar","content":"En otro cuenco, mezcla los 100 g de zumo de naranja, los 80 g de aceite y los 70 g de azúcar. Remueve con varillas hasta dispersar el azúcar; incorpora todo el anís machacado. Puede quedar algo de azúcar sin disolver y el aceite puede separarse si paras: vuelve a remover antes de combinar. No añadas huevo, leche, licor ni cobertura.","image_url":"/recetas/rollitos-de-anis/paso-03.webp","image_alt":"Rollitos de anís: Mezcla el zumo, el aceite y el azúcar"},{"title":"Forma la masa y déjala reposar","content":"Añade los líquidos a los secos y mezcla con espátula hasta que no quede harina suelta. Junta con las manos limpias, sin amasar como pan ni añadir harina a la mesa. Tapa y deja reposar 10 minutos para hidratar la harina. La masa debe poder formar un cordón sin desmoronarse; si no se consigue con las cantidades propuestas, registra la desviación antes de cambiar agua o harina y recalcula. Enciende el horno a 180 °C, calor arriba y abajo, para precalentar unos 15 minutos mientras formas las piezas.","image_url":"/recetas/rollitos-de-anis/paso-04.webp","image_alt":"Rollitos de anís: Forma la masa y déjala reposar"},{"title":"Da forma a las rosquillas pequeñas","content":"Divide toda la masa en 18 porciones lo más iguales posible, aproximadamente 31 g crudos por pieza; el total propuesto de ingredientes es 561 g, no un peso final medido. Rueda cada porción sobre una superficie limpia sin harina extra en un cordón de unos 16 cm y une los extremos, presionándolos. Forma aros de unos 6 cm de diámetro exterior con hueco abierto. Coloca 9 en cada bandeja en tres filas, separados unos 3 cm; no espolvorees azúcar.","image_url":"/recetas/rollitos-de-anis/paso-05.webp","image_alt":"Rollitos de anís: Da forma a las rosquillas pequeñas"},{"title":"Hornea por tandas y revisa la cocción","content":"Hornea la primera bandeja en la zona central a 180 °C durante unos 18 minutos, hasta que los aros estén firmes, ligeramente dorados por debajo y sin centro húmedo al abrir una pieza. Retira y deja que el horno recupere temperatura unos 4 minutos antes de introducir la segunda bandeja, otros 18 minutos. El margen de cocción es 40 minutos para ambas tandas. Si el centro conserva masa húmeda, prolonga y registra el tiempo; no ajustes solo por el color ni pruebes masa cruda.","image_url":"/recetas/rollitos-de-anis/paso-06.webp","image_alt":"Rollitos de anís: Hornea por tandas y revisa la cocción"},{"title":"Enfría completamente sobre rejilla","content":"Deja cada tanda unos 5 minutos en la bandeja y pasa con una espátula a una rejilla. Reserva unos 30 minutos de enfriado total por tanda, incluidos esos 5; la primera se enfría mientras horneas la segunda, por lo que solo cuentas el enfriado final después de la última tanda. Deja enfriar por completo antes de cerrar un recipiente: deben quedar pequeños aros de textura de galleta, no pan esponjoso, sin glaseado ni decoración añadida.","image_url":"/recetas/rollitos-de-anis/paso-07.webp","image_alt":"Rollitos de anís: Enfría completamente sobre rejilla"},{"title":"Sirve y guarda los rollitos fríos","content":"Se proponen 18 rollitos; una unidad es la ración usada en la estimación nutricional. El plan completo suma 105 minutos: 25 de preparación activa, 10 de reposo, 40 de horno por tandas y 30 de enfriado final; el precalentado se solapa con el formado. Cantidades, rendimiento y tiempos pendientes de prueba de cocina. Como propuesta doméstica de calidad sin ensayo de conservación, guarda completamente fríos en recipiente hermético, en lugar fresco y seco, hasta 3 días; si se humedecen o aparece moho, descarta sin probar.","image_url":"/recetas/rollitos-de-anis/portada.webp","image_alt":"Rollitos de anís: Sirve y guarda los rollitos fríos"}],"nutrition":{"calories":118.4,"protein_g":1.8,"carbs_g":17.4,"fat_g":4.7,"saturated_fat_g":0.6,"fiber_g":0.5,"sodium_mg":48.0,"estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"harina de trigo de uso común","edible_grams":300,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"calories":364,"protein_g":10.3,"carbs_g":76.3,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2.0},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"aceite de oliva","edible_grams":80,"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"calories":884,"protein_g":0.0,"carbs_g":0.0,"fat_g":100,"saturated_fat_g":13.8,"fiber_g":0.0,"sugar_g":0.0,"sodium_mg":2.0},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients"},{"ingredient":"zumo de naranja crudo","edible_grams":100,"fdc_id":169098,"fdc_description":"Orange juice, raw (Includes foods for USDA's Food Distribution Program)","per_100g":{"calories":45.0,"protein_g":0.7,"carbs_g":10.4,"fat_g":0.2,"saturated_fat_g":0.024,"fiber_g":0.2,"sugar_g":8.4,"sodium_mg":1.0},"source_url":"https://fdc.nal.usda.gov/food-details/169098/nutrients"},{"ingredient":"azúcar blanco granulado","edible_grams":70,"fdc_id":169655,"fdc_description":"Sugars, granulated","per_100g":{"calories":387,"protein_g":0.0,"carbs_g":100,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.0,"sugar_g":99.8,"sodium_mg":1.0},"source_url":"https://fdc.nal.usda.gov/food-details/169655/nutrients"},{"ingredient":"semillas alimentarias de anís verde","edible_grams":4,"fdc_id":171316,"fdc_description":"Spices, anise seed","per_100g":{"calories":337,"protein_g":17.6,"carbs_g":50.0,"fat_g":15.9,"saturated_fat_g":0.586,"fiber_g":14.6,"sodium_mg":16.0},"source_url":"https://fdc.nal.usda.gov/food-details/171316/nutrients"},{"ingredient":"polvo de hornear de doble acción","edible_grams":6,"fdc_id":172804,"fdc_description":"Leavening agents, baking powder, double-acting, straight phosphate","per_100g":{"calories":51.0,"protein_g":0.1,"carbs_g":24.1,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.2,"sugar_g":0.0,"sodium_mg":7890.0},"source_url":"https://fdc.nal.usda.gov/food-details/172804/nutrients"},{"ingredient":"sal fina","edible_grams":1,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0.0,"protein_g":0.0,"carbs_g":0.0,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.0,"sugar_g":0.0,"sodium_mg":38800.0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"}],"serving_size":"Una unidad de las 18 propuestas; peso final pendiente de confirmación","method":"Suma cada nutriente presente en las siete fichas USDA de toda la fórmula y divide entre 18. No inventa pérdidas de horno o manipulación; omite azúcares totales porque no constan en la ficha de anís.","note":"Estimación de formulación sin ensayo de cocina ni análisis de laboratorio. Los 561 g son suma cruda, no peso final medido. Azúcares totales pendientes: USDA171316 no informa ese nutriente, sin sustitución por cero. Marca del impulsor, zumo y rendimiento real pueden cambiar las cifras.","missing_nutrients":["sugar_g"]},"image_url":"/recetas/rollitos-de-anis/portada.webp","gallery":[{"url":"/recetas/rollitos-de-anis/portada.webp","alt":"Pequeños aros de galleta de anís verde ligeramente dorados, sin glaseado, en un plato blanco"}],"published":true,"editorial_status":"published","keywords":["rollitos de anís","rosquillas de anís al horno","galletas de anís verde","rollitos con naranja"],"notes":"Propuesta original de aros horneados con anís verde alimentario, aceite de oliva y zumo de naranja; no son pan fermentado ni rosquillas fritas. No contiene huevo, leche ni licor como ingredientes, pero no se afirma ausencia de alérgenos o trazas: contiene trigo/gluten y deben revisarse etiquetas y contaminación cruzada. Usa Pimpinella anisum de uso alimentario; anís estrellado, hinojo y extractos no son sustitutos equivalentes. No se ofrece una equivalencia de dosis para licores o aceites esenciales. Cantidades, 18 unidades y textura están propuestas y pendientes de prueba de cocina. La masa completa suma 561 g crudos; no se afirma peso final, evaporación ni pérdida de manipulación medida. Usa todo el aceite, zumo y anís y no añadas harina para formar ni azúcar para acabar. Cambiar zumo, harina, aceite o azúcar altera hidratación, textura y nutrición; registra y recalcula sin prometer el mismo resultado. El precalentado se solapa con el formado y el enfriado de la primera tanda con el horneado de la segunda; el tiempo completo es 105 minutos. La harina es un alimento crudo: no pruebes la masa, limpia manos y utensilios y hornea hasta que la pieza esté cocida por dentro. Lava la naranja con agua corriente antes de cortarla, sin jabón. Como propuesta de calidad no ensayada, enfría por completo y guarda hasta 3 días en recipiente hermético, fresco y seco; la humedad y el clima pueden acortar ese plazo. Si hay moho o humedad anómala, descarta sin probar. No se establece una vida útil comercial ni congelación verificada. Nutrición estimada con siete fichas USDA, fórmula íntegra dividida entre 18: se publican únicamente nutrientes presentes en todas las fichas. La ficha de anís no informa azúcares totales; quedan pendientes y no se reemplazan por cero.","seo":{"title":"Rollitos de anís al horno con naranja: receta","description":"Rollitos de anís verde con naranja y aceite: 18 unidades propuestas, dos tandas de horno, enfriado completo y nutrición estimada. Sin prueba de cocina confirmada.","image_alt":"Pequeños aros de galleta de anís verde ligeramente dorados, sin glaseado, en un plato blanco","image_variants":["/recetas/rollitos-de-anis/portada-1x1.webp","/recetas/rollitos-de-anis/portada-4x3.webp","/recetas/rollitos-de-anis/portada-16x9.webp"],"faq":[{"q":"¿Estos rollitos son pan o rosquillas fritas?","a":"Son aros pequeños horneados de textura de galleta, con impulsor químico. No llevan levadura de panadería, fritura, licor ni glaseado. Las cantidades y la textura son una propuesta original pendiente de prueba de cocina."},{"q":"¿Puedo sustituir el anís verde por anís estrellado o licor?","a":"No se propone esa equivalencia. Usa 4 g de semillas de anís verde alimentario y conserva toda la semilla machacada. Otras especias, licores y extractos cambian sabor, composición e hidratación; requieren otra fórmula y cálculo."},{"q":"¿Por qué no aparece el total de azúcares y cuánto se conservan?","a":"La ficha USDA del anís no informa azúcares; no se inventa cero ni se publica una suma incompleta como total. Los siete nutrientes disponibles se estiman por una de las 18 unidades. La propuesta de calidad sin ensayo es hasta 3 días completamente fríos, herméticos, frescos y secos; humedad y clima pueden acortar el plazo."}]},"content_html":"<p>Pequeños rollitos de anís verde horneados, con aceite de oliva y zumo de naranja, de textura de galleta. Fórmula original propuesta para 18 unidades, sin licor, huevo ni leche añadidos; 105 minutos completos con dos tandas y enfriado, pendientes de ensayo de cocina.</p><p>Propuesta original de aros horneados con anís verde alimentario, aceite de oliva y zumo de naranja; no son pan fermentado ni rosquillas fritas. No contiene huevo, leche ni licor como ingredientes, pero no se afirma ausencia de alérgenos o trazas: contiene trigo/gluten y deben revisarse etiquetas y contaminación cruzada. Usa Pimpinella anisum de uso alimentario; anís estrellado, hinojo y extractos no son sustitutos equivalentes. No se ofrece una equivalencia de dosis para licores o aceites esenciales. Cantidades, 18 unidades y textura están propuestas y pendientes de prueba de cocina. La masa completa suma 561 g crudos; no se afirma peso final, evaporación ni pérdida de manipulación medida. Usa todo el aceite, zumo y anís y no añadas harina para formar ni azúcar para acabar. Cambiar zumo, harina, aceite o azúcar altera hidratación, textura y nutrición; registra y recalcula sin prometer el mismo resultado. El precalentado se solapa con el formado y el enfriado de la primera tanda con el horneado de la segunda; el tiempo completo es 105 minutos. La harina es un alimento crudo: no pruebes la masa, limpia manos y utensilios y hornea hasta que la pieza esté cocida por dentro. Lava la naranja con agua corriente antes de cortarla, sin jabón. Como propuesta de calidad no ensayada, enfría por completo y guarda hasta 3 días en recipiente hermético, fresco y seco; la humedad y el clima pueden acortar ese plazo. Si hay moho o humedad anómala, descarta sin probar. No se establece una vida útil comercial ni congelación verificada. Nutrición estimada con siete fichas USDA, fórmula íntegra dividida entre 18: se publican únicamente nutrientes presentes en todas las fichas. La ficha de anís no informa azúcares totales; quedan pendientes y no se reemplazan por cero.</p>"},{"id":"8eca4166-2974-5f6b-93b2-072a47599f6f","recipe_group_id":"f2371d66-d49e-4092-94d0-7e3e2584aa39","slug":"anis-brotchen","public_path":"/de/anis-brotchen","source_url":"https://manualdecocina.com/de/anis-brotchen/","language":"de","title":"Gebackene Anisringe mit Orangensaft","excerpt":"Kleine Aniskekse mit Orange und Olivenöl: Zutatenmengen, Ruhezeit, zwei Backdurchgänge und vollständiges Abkühlen mit geschätzten USDA-Nährwerten.","summary":"Kleine gebackene Keksringe mit grünen Anissamen, Olivenöl und Orangensaft. Eigenständig vorgeschlagene Rezeptur für 18 Stück ohne zugesetzten Likör, Ei oder Milch; 105 Minuten mit zwei Backdurchgängen und Abkühlen, noch nicht in der Küche erprobt.","category":"Desserts","category_slug":"postres","difficulty":"Einfach","course":"Kekse","cuisine":"Spanisch inspiriert","prep_time_minutes":25,"cook_time_minutes":40,"total_time_minutes":105,"servings":18,"ingredients":[{"name":"Weizenmehl für den allgemeinen Gebrauch","amount":"300","unit":"g","group":"Teig"},{"name":"Olivenöl","amount":"80","unit":"g","group":"Teig"},{"name":"roher, frisch gepresster Orangensaft ohne Kerne","amount":"100","unit":"g","group":"Teig"},{"name":"weißer Kristallzucker","amount":"70","unit":"g","group":"Teig"},{"name":"grüne Anissamen in Lebensmittelqualität (Pimpinella anisum)","amount":"4","unit":"g","group":"Aroma und Backtriebmittel"},{"name":"doppelt wirkendes Backpulver","amount":"6","unit":"g","group":"Aroma und Backtriebmittel"},{"name":"feines Salz","amount":"1","unit":"g","group":"Aroma und Backtriebmittel"}],"steps":[{"title":"Zutaten und Bleche vorbereiten","content":"Waage, Schüsseln, Mörser, Teigschaber, Messer und zwei etwa 30 × 40 cm große Bleche mit Backpapier bereitstellen, ohne zusätzliches Fett. Die Orange vor dem Aufschneiden unter fließendem Wasser waschen und auspressen; Kerne entfernen und 100 g Saft abwiegen. Separat 300 g Mehl, 80 g Öl, 70 g Zucker, 4 g grüne Anissamen, 6 g Backpulver und 1 g Salz abwiegen. Grüne Anissamen in Lebensmittelqualität verwenden, keinen Sternanis, Fenchel oder Likör.","image_url":"/recetas/rollitos-de-anis/paso-01.webp","image_alt":"Gebackene Anisringe mit Orangensaft: Zutaten und Bleche vorbereiten"},{"title":"Anis zerstoßen und trockene Zutaten mischen","content":"Die 4 g Anis kurz im Mörser zerstoßen, sodass die Samen aufbrechen; nichts entfernen. In einer Schüssel 300 g Mehl, 6 g Backpulver und 1 g Salz mit einem Löffel gleichmäßig vermischen. Diese Version verwendet chemisches Backtriebmittel, keine Bäckerhefe. Weder rohes Mehl noch rohen Teig probieren, auch wenn kein Ei enthalten ist.","image_url":"/recetas/rollitos-de-anis/paso-02.webp","image_alt":"Gebackene Anisringe mit Orangensaft: Anis zerstoßen und trockene Zutaten mischen"},{"title":"Saft, Öl und Zucker verrühren","content":"In einer zweiten Schüssel 100 g Orangensaft, 80 g Öl und 70 g Zucker verrühren. Mit einem Schneebesen den Zucker verteilen und den gesamten zerstoßenen Anis zugeben. Etwas Zucker kann ungelöst bleiben und das Öl beim Stehen trennen: vor dem Zusammenführen erneut umrühren. Kein Ei, keine Milch, keinen Likör und keine Glasur hinzufügen.","image_url":"/recetas/rollitos-de-anis/paso-03.webp","image_alt":"Gebackene Anisringe mit Orangensaft: Saft, Öl und Zucker verrühren"},{"title":"Teig verbinden und ruhen lassen","content":"Flüssigkeit zu den trockenen Zutaten geben und mit einem Teigschaber mischen, bis kein loses Mehl bleibt. Mit sauberen Händen zusammenfügen, ohne wie Brot zu kneten oder die Arbeitsfläche zu bemehlen. Abdecken und 10 Minuten ruhen lassen, damit das Mehl Feuchtigkeit aufnimmt. Der Teig soll sich ohne Zerbröseln zu einer Rolle formen lassen; gelingt das mit den vorgeschlagenen Mengen nicht, die Abweichung vor Änderung von Wasser oder Mehl dokumentieren und neu berechnen. Den Ofen auf 180 °C Ober-/Unterhitze stellen und etwa 15 Minuten während des Formens vorheizen.","image_url":"/recetas/rollitos-de-anis/paso-04.webp","image_alt":"Gebackene Anisringe mit Orangensaft: Teig verbinden und ruhen lassen"},{"title":"Kleine Ringe formen","content":"Den gesamten Teig in 18 möglichst gleiche Portionen teilen, ungefähr 31 g Rohteig je Stück; die vorgeschlagene Zutatenmenge von 561 g ist kein gemessenes Endgewicht. Jede Portion auf sauberer, unbemehlter Fläche zu einer etwa 16 cm langen Rolle formen und die Enden zusammendrücken. Ringe mit etwa 6 cm Außendurchmesser und offener Mitte formen. Je 9 Stück in drei Reihen mit etwa 3 cm Abstand auf jedes Blech legen; nicht mit Zucker bestreuen.","image_url":"/recetas/rollitos-de-anis/paso-05.webp","image_alt":"Gebackene Anisringe mit Orangensaft: Kleine Ringe formen"},{"title":"Nacheinander backen und prüfen","content":"Das erste Blech auf mittlerer Höhe bei 180 °C etwa 18 Minuten backen, bis die Ringe fest, unten leicht gebräunt und beim Öffnen innen nicht mehr feucht sind. Herausnehmen und den Ofen etwa 4 Minuten wieder auf Temperatur kommen lassen, dann das zweite Blech weitere 18 Minuten backen. Für beide Durchgänge sind 40 Minuten vorgesehen. Bleibt innen feuchter Teig, weiterbacken und die Zeit dokumentieren; nicht allein nach Farbe entscheiden und keinen rohen Teig probieren.","image_url":"/recetas/rollitos-de-anis/paso-06.webp","image_alt":"Gebackene Anisringe mit Orangensaft: Nacheinander backen und prüfen"},{"title":"Auf einem Gitter vollständig abkühlen","content":"Jeden Durchgang etwa 5 Minuten auf dem Blech stehen lassen, dann mit einem Teigschaber auf ein Gitter setzen. Für jeden Durchgang insgesamt etwa 30 Minuten Abkühlen vorsehen, einschließlich dieser 5; der erste kühlt während des zweiten Backdurchgangs, deshalb nur das abschließende Abkühlen nach dem letzten Durchgang zusätzlich zählen. Vor dem Verschließen vollständig abkühlen lassen: kleine Ringe mit Keksstruktur, kein luftiges Brot, ohne Glasur oder zusätzliche Dekoration.","image_url":"/recetas/rollitos-de-anis/paso-07.webp","image_alt":"Gebackene Anisringe mit Orangensaft: Auf einem Gitter vollständig abkühlen"},{"title":"Kalt servieren und aufbewahren","content":"Vorgeschlagen sind 18 Anisringe; ein Stück entspricht der Portion für die Nährwertschätzung. Insgesamt sind 105 Minuten geplant: 25 aktive Vorbereitung, 10 Ruhezeit, 40 Backen in Durchgängen und 30 abschließendes Abkühlen; das Vorheizen läuft während des Formens. Mengen, Ausbeute und Zeiten sind noch nicht in der Küche geprüft. Als ungeprüfter Vorschlag für häusliche Qualität vollständig kalt in einem luftdichten Behälter kühl und trocken bis zu 3 Tage aufbewahren; bei Feuchtigkeit oder Schimmel ohne Probieren entsorgen.","image_url":"/recetas/rollitos-de-anis/portada.webp","image_alt":"Gebackene Anisringe mit Orangensaft: Kalt servieren und aufbewahren"}],"nutrition":{"calories":118.4,"protein_g":1.8,"carbs_g":17.4,"fat_g":4.7,"saturated_fat_g":0.6,"fiber_g":0.5,"sodium_mg":48.0,"estimated":true,"source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"Weizenmehl für den allgemeinen Gebrauch","edible_grams":300,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"calories":364,"protein_g":10.3,"carbs_g":76.3,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2.0},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"Olivenöl","edible_grams":80,"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"calories":884,"protein_g":0.0,"carbs_g":0.0,"fat_g":100,"saturated_fat_g":13.8,"fiber_g":0.0,"sugar_g":0.0,"sodium_mg":2.0},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients"},{"ingredient":"roher, frisch gepresster Orangensaft ohne Kerne","edible_grams":100,"fdc_id":169098,"fdc_description":"Orange juice, raw (Includes foods for USDA's Food Distribution Program)","per_100g":{"calories":45.0,"protein_g":0.7,"carbs_g":10.4,"fat_g":0.2,"saturated_fat_g":0.024,"fiber_g":0.2,"sugar_g":8.4,"sodium_mg":1.0},"source_url":"https://fdc.nal.usda.gov/food-details/169098/nutrients"},{"ingredient":"weißer Kristallzucker","edible_grams":70,"fdc_id":169655,"fdc_description":"Sugars, granulated","per_100g":{"calories":387,"protein_g":0.0,"carbs_g":100,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.0,"sugar_g":99.8,"sodium_mg":1.0},"source_url":"https://fdc.nal.usda.gov/food-details/169655/nutrients"},{"ingredient":"grüne Anissamen in Lebensmittelqualität (Pimpinella anisum)","edible_grams":4,"fdc_id":171316,"fdc_description":"Spices, anise seed","per_100g":{"calories":337,"protein_g":17.6,"carbs_g":50.0,"fat_g":15.9,"saturated_fat_g":0.586,"fiber_g":14.6,"sodium_mg":16.0},"source_url":"https://fdc.nal.usda.gov/food-details/171316/nutrients"},{"ingredient":"doppelt wirkendes Backpulver","edible_grams":6,"fdc_id":172804,"fdc_description":"Leavening agents, baking powder, double-acting, straight phosphate","per_100g":{"calories":51.0,"protein_g":0.1,"carbs_g":24.1,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.2,"sugar_g":0.0,"sodium_mg":7890.0},"source_url":"https://fdc.nal.usda.gov/food-details/172804/nutrients"},{"ingredient":"feines Salz","edible_grams":1,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0.0,"protein_g":0.0,"carbs_g":0.0,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.0,"sugar_g":0.0,"sodium_mg":38800.0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"}],"serving_size":"Eines der 18 vorgeschlagenen Stück; Endgewicht noch nicht bestätigt","method":"Für jeden Nährstoff mit Angaben in allen sieben USDA-Datensätzen die ganze Rezeptur summieren und durch 18 teilen. Keine erfundenen Back- oder Formverluste; Gesamtzucker weggelassen, weil im Anisdatensatz keine Angabe steht.","note":"Rezepturschätzung ohne Küchenversuch oder Laboranalyse. 561 g sind die rohe Summe, kein gemessenes Endgewicht. Gesamtzucker offen: USDA171316 berichtet diesen Nährstoff nicht, kein Ersatz durch null. Backpulvermarke, Saft und tatsächliche Ausbeute können Werte verändern.","missing_nutrients":["sugar_g"]},"image_url":"/recetas/rollitos-de-anis/portada.webp","gallery":[{"url":"/recetas/rollitos-de-anis/portada.webp","alt":"Kleine leicht goldbraune Keksringe mit grünen Anissamen ohne Glasur auf einem weißen Teller"}],"published":true,"editorial_status":"published","keywords":["Anisringe","Aniskekse mit Orange","gebackene Aniskekse","Anis ohne Likör"],"notes":"Eigenständiger Vorschlag für gebackene Ringe mit grünen Anissamen in Lebensmittelqualität, Olivenöl und Orangensaft; kein fermentiertes Brot und keine frittierten Ringe. Ei, Milch und Likör sind keine Zutaten, dennoch wird keine Allergen- oder Spurenfreiheit behauptet: enthält Weizen/Gluten; Etiketten und Kreuzkontakt prüfen. Pimpinella anisum in Lebensmittelqualität verwenden; Sternanis, Fenchel und Extrakte sind keine gleichwertigen Ersatzstoffe. Keine Dosisequivalenz für Liköre oder ätherische Öle. Mengen, 18 Stück und Konsistenz sind vorgeschlagen und nicht in der Küche erprobt. Der gesamte Teig enthält 561 g rohe Zutaten; Endgewicht, Verdunstung und Formverluste sind nicht gemessen. Alles Öl, allen Saft und Anis verwenden, ohne zusätzliches Mehl zum Formen oder abschließenden Zucker. Änderungen an Saft, Mehl, Öl oder Zucker verändern Feuchtigkeit, Konsistenz und Nährwerte: dokumentieren und neu berechnen, ohne dasselbe Ergebnis zu versprechen. Vorheizen und Formen laufen parallel, ebenso das Abkühlen des ersten und Backen des zweiten Blechs; Gesamtzeit 105 Minuten. Mehl ist ein rohes Lebensmittel: Teig nicht probieren, Hände und Geräte reinigen und innen durchbacken. Orange vor dem Schneiden mit fließendem Wasser ohne Seife waschen. Als ungeprüfter Qualitätsvorschlag vollständig abgekühlt bis zu 3 Tage luftdicht, kühl und trocken lagern; Feuchtigkeit und Klima können die Zeit verkürzen. Bei Schimmel oder ungewöhnlicher Feuchtigkeit ohne Probieren entsorgen. Keine verifizierte gewerbliche Haltbarkeit oder Tiefkühllagerung. Nährwerte anhand sieben USDA-Datensätzen geschätzt, ganze Rezeptur geteilt durch 18: nur Nährstoffe mit Angaben in allen Datensätzen werden berichtet. Der Anisdatensatz enthält keine Gesamtzuckerangabe; diese bleibt offen und wird nicht durch null ersetzt.","seo":{"title":"Anisringe mit Orange aus dem Ofen: Rezept","description":"Gebackene Keksringe mit grünen Anissamen, Orange und Öl: 18 vorgeschlagene Stück, zwei Backdurchgänge, vollständiges Abkühlen und geschätzte Nährwerte.","image_alt":"Kleine leicht goldbraune Keksringe mit grünen Anissamen ohne Glasur auf einem weißen Teller","image_variants":["/recetas/rollitos-de-anis/portada-1x1.webp","/recetas/rollitos-de-anis/portada-4x3.webp","/recetas/rollitos-de-anis/portada-16x9.webp"],"faq":[{"q":"Sind diese Anisringe Brot oder frittiertes Gebäck?","a":"Es sind kleine gebackene Ringe mit Keksstruktur und chemischem Backtriebmittel. Keine Bäckerhefe, kein Frittieren, Likör oder Glasur. Mengen und Konsistenz sind ein eigenständiger Vorschlag, der noch nicht in der Küche erprobt ist."},{"q":"Kann ich grüne Anissamen durch Sternanis oder Likör ersetzen?","a":"Dafür wird keine Gleichwertigkeit vorgeschlagen. 4 g grüne Anissamen in Lebensmittelqualität verwenden und den gesamten zerstoßenen Samen behalten. Andere Gewürze, Liköre und Extrakte verändern Geschmack, Zusammensetzung und Feuchtigkeit und benötigen eine andere Rezeptur samt Berechnung."},{"q":"Warum fehlt Gesamtzucker und wie lange sind sie haltbar?","a":"Der USDA-Anisdatensatz berichtet keinen Zuckerwert; weder null noch eine unvollständige Summe wird als Gesamtwert erfunden. Die sieben verfügbaren Nährstoffe werden pro einem der 18 Stück geschätzt. Ungeprüfter Qualitätsvorschlag: bis zu 3 Tage vollständig kalt, luftdicht, kühl und trocken; Feuchtigkeit und Klima können die Zeit verkürzen."}]},"content_html":"<p>Kleine gebackene Keksringe mit grünen Anissamen, Olivenöl und Orangensaft. Eigenständig vorgeschlagene Rezeptur für 18 Stück ohne zugesetzten Likör, Ei oder Milch; 105 Minuten mit zwei Backdurchgängen und Abkühlen, noch nicht in der Küche erprobt.</p><p>Eigenständiger Vorschlag für gebackene Ringe mit grünen Anissamen in Lebensmittelqualität, Olivenöl und Orangensaft; kein fermentiertes Brot und keine frittierten Ringe. Ei, Milch und Likör sind keine Zutaten, dennoch wird keine Allergen- oder Spurenfreiheit behauptet: enthält Weizen/Gluten; Etiketten und Kreuzkontakt prüfen. Pimpinella anisum in Lebensmittelqualität verwenden; Sternanis, Fenchel und Extrakte sind keine gleichwertigen Ersatzstoffe. Keine Dosisequivalenz für Liköre oder ätherische Öle. Mengen, 18 Stück und Konsistenz sind vorgeschlagen und nicht in der Küche erprobt. Der gesamte Teig enthält 561 g rohe Zutaten; Endgewicht, Verdunstung und Formverluste sind nicht gemessen. Alles Öl, allen Saft und Anis verwenden, ohne zusätzliches Mehl zum Formen oder abschließenden Zucker. Änderungen an Saft, Mehl, Öl oder Zucker verändern Feuchtigkeit, Konsistenz und Nährwerte: dokumentieren und neu berechnen, ohne dasselbe Ergebnis zu versprechen. Vorheizen und Formen laufen parallel, ebenso das Abkühlen des ersten und Backen des zweiten Blechs; Gesamtzeit 105 Minuten. Mehl ist ein rohes Lebensmittel: Teig nicht probieren, Hände und Geräte reinigen und innen durchbacken. Orange vor dem Schneiden mit fließendem Wasser ohne Seife waschen. Als ungeprüfter Qualitätsvorschlag vollständig abgekühlt bis zu 3 Tage luftdicht, kühl und trocken lagern; Feuchtigkeit und Klima können die Zeit verkürzen. Bei Schimmel oder ungewöhnlicher Feuchtigkeit ohne Probieren entsorgen. Keine verifizierte gewerbliche Haltbarkeit oder Tiefkühllagerung. Nährwerte anhand sieben USDA-Datensätzen geschätzt, ganze Rezeptur geteilt durch 18: nur Nährstoffe mit Angaben in allen Datensätzen werden berichtet. Der Anisdatensatz enthält keine Gesamtzuckerangabe; diese bleibt offen und wird nicht durch null ersetzt.</p>"},{"id":"7b0c1510-a5b5-5ae8-991b-a3a90d48958d","recipe_group_id":"f2371d66-d49e-4092-94d0-7e3e2584aa39","slug":"anise-rolls","public_path":"/en/anise-rolls","source_url":null,"language":"en","title":"Baked green anise biscuit rings with orange","excerpt":"Small anise biscuit rings with orange and olive oil: grouped quantities, resting, two oven batches and full cooling, with estimated USDA nutrition and missing data stated.","summary":"Small baked biscuit rings made with green anise seeds, olive oil and orange juice. An original proposed formula for 18 pieces, with no added liqueur, egg or milk; 105 minutes including two oven batches and cooling, pending a kitchen trial.","category":"Desserts","category_slug":"postres","difficulty":"Easy","course":"Biscuits","cuisine":"Spanish inspired","prep_time_minutes":25,"cook_time_minutes":40,"total_time_minutes":105,"servings":18,"ingredients":[{"name":"all-purpose wheat flour","amount":"300","unit":"g","group":"Dough"},{"name":"olive oil","amount":"80","unit":"g","group":"Dough"},{"name":"raw freshly squeezed orange juice, seeds removed","amount":"100","unit":"g","group":"Dough"},{"name":"white granulated sugar","amount":"70","unit":"g","group":"Dough"},{"name":"food-grade green anise seeds (Pimpinella anisum)","amount":"4","unit":"g","group":"Flavor and raising agent"},{"name":"double-acting baking powder","amount":"6","unit":"g","group":"Flavor and raising agent"},{"name":"fine salt","amount":"1","unit":"g","group":"Flavor and raising agent"}],"steps":[{"title":"Prepare the ingredients and trays","content":"Set out scales, bowls, a mortar, spatula, knife and two trays about 30 × 40 cm lined with baking parchment, without extra grease. Wash the orange under running water before cutting and squeeze it; remove seeds and weigh 100 g juice. Separately weigh 300 g flour, 80 g oil, 70 g sugar, 4 g green anise seeds, 6 g baking powder and 1 g salt. Use food-grade green anise seeds, not star anise, fennel or liqueur.","image_url":"/recetas/rollitos-de-anis/paso-01.webp","image_alt":"Baked green anise biscuit rings with orange: Prepare the ingredients and trays"},{"title":"Crush the anise and combine dry ingredients","content":"Briefly crush the 4 g anise in the mortar to break the seeds without discarding any part. Use a spoon to distribute the 300 g flour, 6 g baking powder and 1 g salt evenly in a bowl. This version uses a chemical raising agent rather than baker's yeast. Do not taste raw flour or dough even though there is no egg.","image_url":"/recetas/rollitos-de-anis/paso-02.webp","image_alt":"Baked green anise biscuit rings with orange: Crush the anise and combine dry ingredients"},{"title":"Mix the juice, oil and sugar","content":"In another bowl, combine 100 g orange juice, 80 g oil and 70 g sugar. Whisk to disperse the sugar and add all the crushed anise. Some sugar may remain undissolved and the oil may separate when you stop: stir again before combining. Do not add egg, milk, liqueur or a topping.","image_url":"/recetas/rollitos-de-anis/paso-03.webp","image_alt":"Baked green anise biscuit rings with orange: Mix the juice, oil and sugar"},{"title":"Bring the dough together and rest it","content":"Add the liquids to the dry ingredients and mix with a spatula until no loose flour remains. Bring together with clean hands without kneading like bread or flouring the worktop. Cover and rest for 10 minutes to hydrate the flour. The dough should roll into a cord without crumbling; if the proposed amounts do not achieve this, record the deviation before changing water or flour and recalculate. Set the oven to 180 °C, conventional top and bottom heat, to preheat for about 15 minutes while shaping.","image_url":"/recetas/rollitos-de-anis/paso-04.webp","image_alt":"Baked green anise biscuit rings with orange: Bring the dough together and rest it"},{"title":"Shape small rings","content":"Divide all the dough into 18 portions as evenly as possible, about 31 g raw dough each; the proposed total of 561 g ingredients is not a measured finished weight. Roll each portion on a clean unfloured surface into a cord about 16 cm long and press its ends together. Make rings about 6 cm across externally with an open hole. Arrange 9 on each tray in three rows, about 3 cm apart; do not dust with sugar.","image_url":"/recetas/rollitos-de-anis/paso-05.webp","image_alt":"Baked green anise biscuit rings with orange: Shape small rings"},{"title":"Bake in batches and check the centers","content":"Bake the first tray on the middle level at 180 °C for about 18 minutes, until the rings are firm, lightly golden underneath and not wet inside when one is opened. Remove and allow about 4 minutes for the oven to recover its temperature before baking the second tray for another 18 minutes. Allow 40 minutes for both batches. If the center remains wet dough, extend baking and record the time; do not judge only by color or taste raw dough.","image_url":"/recetas/rollitos-de-anis/paso-06.webp","image_alt":"Baked green anise biscuit rings with orange: Bake in batches and check the centers"},{"title":"Cool completely on a rack","content":"Leave each batch on its tray for about 5 minutes, then transfer to a wire rack with a spatula. Allow about 30 minutes total cooling per batch, including those 5; the first cools while the second bakes, so count only the final cooling after the last batch separately. Cool fully before sealing a container: these should be small biscuit-textured rings, not fluffy bread, without icing or added decoration.","image_url":"/recetas/rollitos-de-anis/paso-07.webp","image_alt":"Baked green anise biscuit rings with orange: Cool completely on a rack"},{"title":"Serve and store the cooled rings","content":"The proposed yield is 18 rings; one piece is the serving used for estimated nutrition. The full plan totals 105 minutes: 25 active preparation, 10 resting, 40 baking in batches and 30 final cooling; preheating overlaps shaping. Quantities, yield and timings await a kitchen trial. As an untested home quality suggestion, store completely cool in an airtight container somewhere cool and dry for up to 3 days; discard without tasting if dampness or mold develops.","image_url":"/recetas/rollitos-de-anis/portada.webp","image_alt":"Baked green anise biscuit rings with orange: Serve and store the cooled rings"}],"nutrition":{"calories":118.4,"protein_g":1.8,"carbs_g":17.4,"fat_g":4.7,"saturated_fat_g":0.6,"fiber_g":0.5,"sodium_mg":48.0,"estimated":true,"source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"all-purpose wheat flour","edible_grams":300,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"calories":364,"protein_g":10.3,"carbs_g":76.3,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2.0},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"olive oil","edible_grams":80,"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"calories":884,"protein_g":0.0,"carbs_g":0.0,"fat_g":100,"saturated_fat_g":13.8,"fiber_g":0.0,"sugar_g":0.0,"sodium_mg":2.0},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients"},{"ingredient":"raw freshly squeezed orange juice, seeds removed","edible_grams":100,"fdc_id":169098,"fdc_description":"Orange juice, raw (Includes foods for USDA's Food Distribution Program)","per_100g":{"calories":45.0,"protein_g":0.7,"carbs_g":10.4,"fat_g":0.2,"saturated_fat_g":0.024,"fiber_g":0.2,"sugar_g":8.4,"sodium_mg":1.0},"source_url":"https://fdc.nal.usda.gov/food-details/169098/nutrients"},{"ingredient":"white granulated sugar","edible_grams":70,"fdc_id":169655,"fdc_description":"Sugars, granulated","per_100g":{"calories":387,"protein_g":0.0,"carbs_g":100,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.0,"sugar_g":99.8,"sodium_mg":1.0},"source_url":"https://fdc.nal.usda.gov/food-details/169655/nutrients"},{"ingredient":"food-grade green anise seeds (Pimpinella anisum)","edible_grams":4,"fdc_id":171316,"fdc_description":"Spices, anise seed","per_100g":{"calories":337,"protein_g":17.6,"carbs_g":50.0,"fat_g":15.9,"saturated_fat_g":0.586,"fiber_g":14.6,"sodium_mg":16.0},"source_url":"https://fdc.nal.usda.gov/food-details/171316/nutrients"},{"ingredient":"double-acting baking powder","edible_grams":6,"fdc_id":172804,"fdc_description":"Leavening agents, baking powder, double-acting, straight phosphate","per_100g":{"calories":51.0,"protein_g":0.1,"carbs_g":24.1,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.2,"sugar_g":0.0,"sodium_mg":7890.0},"source_url":"https://fdc.nal.usda.gov/food-details/172804/nutrients"},{"ingredient":"fine salt","edible_grams":1,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0.0,"protein_g":0.0,"carbs_g":0.0,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.0,"sugar_g":0.0,"sodium_mg":38800.0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"}],"serving_size":"One of the 18 proposed pieces; finished weight not confirmed","method":"Sum each nutrient reported by all seven USDA records across the whole formula and divide by 18. No invented oven or handling losses; total sugar is omitted because the anise record does not report it.","note":"Formula estimate without a kitchen trial or laboratory analysis. 561 g is the raw sum, not measured finished weight. Total sugars pending: USDA171316 does not report this nutrient, with no zero substitution. Raising-agent brand, juice and actual yield can change the values.","missing_nutrients":["sugar_g"]},"image_url":"/recetas/rollitos-de-anis/portada.webp","gallery":[{"url":"/recetas/rollitos-de-anis/portada.webp","alt":"Small lightly golden green anise biscuit rings without icing on a white plate"}],"published":true,"editorial_status":"published","keywords":["anise biscuit rings","baked anise rolls","orange anise biscuits","anise without liqueur"],"notes":"An original proposed baked ring formula with food-grade green anise, olive oil and orange juice; these are biscuit rings rather than fermented bread or fried doughnuts. Egg, milk and liqueur are not ingredients, but freedom from allergens or traces is not claimed: contains wheat/gluten; check labels and cross-contact. Use food-grade Pimpinella anisum; star anise, fennel and extracts are not equivalent replacements. No dose equivalence is given for liqueurs or essential oils. Quantities, 18 pieces and texture are proposed and await a kitchen trial. The full dough comprises 561 g raw ingredients; finished weight, evaporation and handling losses have not been measured. Use all the oil, juice and anise without extra shaping flour or finishing sugar. Changes to juice, flour, oil or sugar alter hydration, texture and nutrition; record and recalculate without promising the same result. Preheating overlaps shaping, and the first tray's cooling overlaps the second tray's baking; full time is 105 minutes. Flour is a raw food: do not taste dough, clean hands and utensils, and bake until cooked inside. Wash the orange in plain running water before cutting, without soap. As an untested quality suggestion, cool completely and store airtight, cool and dry for up to 3 days; humidity and climate can shorten that period. Discard without tasting if there is mold or unusual dampness. No verified commercial shelf life or freezing period is established. Nutrition is estimated from seven USDA records, the whole formula divided by 18: only nutrients reported in every record are published. The anise record does not report total sugars; that value remains pending and is not replaced with zero.","seo":{"title":"Baked anise rings with orange: step-by-step recipe","description":"Small baked green anise biscuit rings with orange and oil: 18 proposed pieces, two oven batches, full cooling and estimated nutrition. Kitchen trial pending.","image_alt":"Small lightly golden green anise biscuit rings without icing on a white plate","image_variants":["/recetas/rollitos-de-anis/portada-1x1.webp","/recetas/rollitos-de-anis/portada-4x3.webp","/recetas/rollitos-de-anis/portada-16x9.webp"],"faq":[{"q":"Are these rings bread or fried doughnuts?","a":"They are small baked rings with biscuit texture and a chemical raising agent. No baker's yeast, frying, liqueur or icing. Quantities and texture form an original proposal awaiting a kitchen trial."},{"q":"Can star anise or liqueur replace green anise?","a":"No equivalent substitution is proposed. Use 4 g food-grade green anise seeds and retain all the crushed seed. Other spices, liqueurs and extracts change flavor, composition and hydration and require a different formula and calculation."},{"q":"Why is total sugar missing, and how long do they keep?","a":"The USDA anise record does not report sugar; neither zero nor an incomplete sum is invented as a total. The seven available nutrients are estimated for one of the 18 pieces. The untested quality suggestion is up to 3 days fully cool, airtight, cool and dry; humidity and climate can shorten that time."}]},"content_html":"<p>Small baked biscuit rings made with green anise seeds, olive oil and orange juice. An original proposed formula for 18 pieces, with no added liqueur, egg or milk; 105 minutes including two oven batches and cooling, pending a kitchen trial.</p><p>An original proposed baked ring formula with food-grade green anise, olive oil and orange juice; these are biscuit rings rather than fermented bread or fried doughnuts. Egg, milk and liqueur are not ingredients, but freedom from allergens or traces is not claimed: contains wheat/gluten; check labels and cross-contact. Use food-grade Pimpinella anisum; star anise, fennel and extracts are not equivalent replacements. No dose equivalence is given for liqueurs or essential oils. Quantities, 18 pieces and texture are proposed and await a kitchen trial. The full dough comprises 561 g raw ingredients; finished weight, evaporation and handling losses have not been measured. Use all the oil, juice and anise without extra shaping flour or finishing sugar. Changes to juice, flour, oil or sugar alter hydration, texture and nutrition; record and recalculate without promising the same result. Preheating overlaps shaping, and the first tray&#x27;s cooling overlaps the second tray&#x27;s baking; full time is 105 minutes. Flour is a raw food: do not taste dough, clean hands and utensils, and bake until cooked inside. Wash the orange in plain running water before cutting, without soap. As an untested quality suggestion, cool completely and store airtight, cool and dry for up to 3 days; humidity and climate can shorten that period. Discard without tasting if there is mold or unusual dampness. No verified commercial shelf life or freezing period is established. Nutrition is estimated from seven USDA records, the whole formula divided by 18: only nutrients reported in every record are published. The anise record does not report total sugars; that value remains pending and is not replaced with zero.</p>"},{"id":"0b2db79a-7640-5fa4-b6e1-9e0e56b0b685","recipe_group_id":"f2371d66-d49e-4092-94d0-7e3e2584aa39","slug":"petits-pains-a-lanis","public_path":"/fr/petits-pains-a-lanis","source_url":"https://manualdecocina.com/fr/petits-pains-a-lanis/","language":"fr","title":"Petits anneaux à l’anis vert et à l’orange au four","excerpt":"Biscuits à l’anis vert, à l’orange et à l’huile : quantités regroupées, repos, deux fournées et refroidissement complet, avec nutrition estimée.","summary":"Petits anneaux au four de texture biscuitée, aux graines d’anis vert, à l’huile d’olive et au jus d’orange. Formule originale proposée pour 18 pièces sans liqueur, œuf ni lait ajoutés ; 105 minutes avec deux fournées et refroidissement, en attente d’essai en cuisine.","category":"Desserts","category_slug":"postres","difficulty":"Facile","course":"Biscuits","cuisine":"Inspiration espagnole","prep_time_minutes":25,"cook_time_minutes":40,"total_time_minutes":105,"servings":18,"ingredients":[{"name":"farine de blé d’usage courant","amount":"300","unit":"g","group":"Pâte"},{"name":"huile d’olive","amount":"80","unit":"g","group":"Pâte"},{"name":"jus d’orange cru fraîchement pressé, sans pépins","amount":"100","unit":"g","group":"Pâte"},{"name":"sucre blanc en poudre","amount":"70","unit":"g","group":"Pâte"},{"name":"graines alimentaires d’anis vert (Pimpinella anisum)","amount":"4","unit":"g","group":"Arôme et agent levant"},{"name":"levure chimique à double action","amount":"6","unit":"g","group":"Arôme et agent levant"},{"name":"sel fin","amount":"1","unit":"g","group":"Arôme et agent levant"}],"steps":[{"title":"Préparer ingrédients et plaques","content":"Préparez balance, bols, mortier, spatule, couteau et deux plaques d’environ 30 × 40 cm couvertes de papier cuisson, sans graisse supplémentaire. Lavez l’orange sous l’eau courante avant de la couper puis pressez-la ; retirez les pépins et pesez 100 g de jus. Pesez séparément 300 g de farine, 80 g d’huile, 70 g de sucre, 4 g d’anis vert, 6 g de levure chimique et 1 g de sel. Utilisez de l’anis vert alimentaire, pas de badiane, fenouil ou liqueur.","image_url":"/recetas/rollitos-de-anis/paso-01.webp","image_alt":"Petits anneaux à l’anis vert et à l’orange au four: Préparer ingrédients et plaques"},{"title":"Écraser l’anis et mélanger les ingrédients secs","content":"Écrasez brièvement les 4 g d’anis au mortier pour briser les graines sans rien retirer. Mélangez dans un bol les 300 g de farine, les 6 g de levure chimique et le 1 g de sel avec une cuillère pour bien les répartir. Cette version utilise un agent levant chimique, pas de levure de boulanger. Ne goûtez ni farine ni pâte crues, même sans œuf.","image_url":"/recetas/rollitos-de-anis/paso-02.webp","image_alt":"Petits anneaux à l’anis vert et à l’orange au four: Écraser l’anis et mélanger les ingrédients secs"},{"title":"Mélanger jus, huile et sucre","content":"Dans un autre bol, mélangez les 100 g de jus d’orange, les 80 g d’huile et les 70 g de sucre. Fouettez pour disperser le sucre et incorporez tout l’anis écrasé. Du sucre peut rester non dissous et l’huile peut se séparer à l’arrêt : remuez de nouveau avant de réunir les mélanges. N’ajoutez ni œuf, ni lait, ni liqueur, ni garniture.","image_url":"/recetas/rollitos-de-anis/paso-03.webp","image_alt":"Petits anneaux à l’anis vert et à l’orange au four: Mélanger jus, huile et sucre"},{"title":"Rassembler la pâte et la laisser reposer","content":"Ajoutez les liquides aux ingrédients secs et mélangez à la spatule jusqu’à disparition de la farine libre. Rassemblez avec les mains propres, sans pétrir comme du pain ni fariner le plan. Couvrez et laissez reposer 10 minutes pour hydrater la farine. La pâte doit former un boudin sans s’émietter ; si les quantités proposées ne le permettent pas, notez l’écart avant de modifier eau ou farine et recalculez. Allumez le four à 180 °C, chaleur voûte et sole, pour environ 15 minutes de préchauffage pendant le façonnage.","image_url":"/recetas/rollitos-de-anis/paso-04.webp","image_alt":"Petits anneaux à l’anis vert et à l’orange au four: Rassembler la pâte et la laisser reposer"},{"title":"Façonner les petits anneaux","content":"Divisez toute la pâte en 18 portions aussi égales que possible, environ 31 g de pâte crue par pièce ; les 561 g d’ingrédients proposés ne sont pas un poids final mesuré. Roulez chaque portion sur une surface propre non farinée en boudin d’environ 16 cm et soudez ses extrémités en appuyant. Formez des anneaux d’environ 6 cm de diamètre extérieur avec un trou ouvert. Disposez 9 pièces sur chaque plaque en trois rangées, espacées d’environ 3 cm ; ne saupoudrez pas de sucre.","image_url":"/recetas/rollitos-de-anis/paso-05.webp","image_alt":"Petits anneaux à l’anis vert et à l’orange au four: Façonner les petits anneaux"},{"title":"Cuire par fournées et vérifier le centre","content":"Enfournez la première plaque au milieu à 180 °C pendant environ 18 minutes, jusqu’à ce que les anneaux soient fermes, légèrement dorés dessous et sans centre humide lorsqu’on ouvre une pièce. Sortez-les et laissez le four retrouver sa température environ 4 minutes avant d’enfourner la seconde plaque pour 18 minutes supplémentaires. Prévoyez 40 minutes pour les deux fournées. Si le centre contient encore de la pâte humide, prolongez et notez la durée ; ne jugez pas seulement la couleur et ne goûtez pas de pâte crue.","image_url":"/recetas/rollitos-de-anis/paso-06.webp","image_alt":"Petits anneaux à l’anis vert et à l’orange au four: Cuire par fournées et vérifier le centre"},{"title":"Refroidir complètement sur une grille","content":"Laissez chaque fournée environ 5 minutes sur la plaque, puis transférez-la sur une grille avec une spatule. Prévoyez environ 30 minutes de refroidissement total par fournée, y compris ces 5 ; la première refroidit pendant la cuisson de la seconde, donc seul le refroidissement final après la dernière fournée s’ajoute séparément. Refroidissez complètement avant de fermer un récipient : petits anneaux de texture biscuitée, pas du pain moelleux, sans glaçage ni décoration ajoutée.","image_url":"/recetas/rollitos-de-anis/paso-07.webp","image_alt":"Petits anneaux à l’anis vert et à l’orange au four: Refroidir complètement sur une grille"},{"title":"Servir et conserver les anneaux froids","content":"Le rendement proposé est de 18 anneaux ; une pièce correspond à la portion utilisée pour la nutrition estimée. Le programme complet totalise 105 minutes : 25 de préparation active, 10 de repos, 40 de cuisson par fournées et 30 de refroidissement final ; le préchauffage se fait pendant le façonnage. Quantités, rendement et durées attendent un essai en cuisine. Comme proposition domestique de qualité sans essai de conservation, gardez complètement froids dans une boîte hermétique, au frais et au sec, jusqu’à 3 jours ; en cas d’humidité ou de moisissure, jetez sans goûter.","image_url":"/recetas/rollitos-de-anis/portada.webp","image_alt":"Petits anneaux à l’anis vert et à l’orange au four: Servir et conserver les anneaux froids"}],"nutrition":{"calories":118.4,"protein_g":1.8,"carbs_g":17.4,"fat_g":4.7,"saturated_fat_g":0.6,"fiber_g":0.5,"sodium_mg":48.0,"estimated":true,"source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"farine de blé d’usage courant","edible_grams":300,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"calories":364,"protein_g":10.3,"carbs_g":76.3,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2.0},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"huile d’olive","edible_grams":80,"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"calories":884,"protein_g":0.0,"carbs_g":0.0,"fat_g":100,"saturated_fat_g":13.8,"fiber_g":0.0,"sugar_g":0.0,"sodium_mg":2.0},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients"},{"ingredient":"jus d’orange cru fraîchement pressé, sans pépins","edible_grams":100,"fdc_id":169098,"fdc_description":"Orange juice, raw (Includes foods for USDA's Food Distribution Program)","per_100g":{"calories":45.0,"protein_g":0.7,"carbs_g":10.4,"fat_g":0.2,"saturated_fat_g":0.024,"fiber_g":0.2,"sugar_g":8.4,"sodium_mg":1.0},"source_url":"https://fdc.nal.usda.gov/food-details/169098/nutrients"},{"ingredient":"sucre blanc en poudre","edible_grams":70,"fdc_id":169655,"fdc_description":"Sugars, granulated","per_100g":{"calories":387,"protein_g":0.0,"carbs_g":100,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.0,"sugar_g":99.8,"sodium_mg":1.0},"source_url":"https://fdc.nal.usda.gov/food-details/169655/nutrients"},{"ingredient":"graines alimentaires d’anis vert (Pimpinella anisum)","edible_grams":4,"fdc_id":171316,"fdc_description":"Spices, anise seed","per_100g":{"calories":337,"protein_g":17.6,"carbs_g":50.0,"fat_g":15.9,"saturated_fat_g":0.586,"fiber_g":14.6,"sodium_mg":16.0},"source_url":"https://fdc.nal.usda.gov/food-details/171316/nutrients"},{"ingredient":"levure chimique à double action","edible_grams":6,"fdc_id":172804,"fdc_description":"Leavening agents, baking powder, double-acting, straight phosphate","per_100g":{"calories":51.0,"protein_g":0.1,"carbs_g":24.1,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.2,"sugar_g":0.0,"sodium_mg":7890.0},"source_url":"https://fdc.nal.usda.gov/food-details/172804/nutrients"},{"ingredient":"sel fin","edible_grams":1,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0.0,"protein_g":0.0,"carbs_g":0.0,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.0,"sugar_g":0.0,"sodium_mg":38800.0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"}],"serving_size":"Une des 18 pièces proposées ; poids final non confirmé","method":"Additionner chaque nutriment présent dans les sept fiches USDA pour toute la formule et diviser par 18. Aucune perte de cuisson ou manipulation inventée ; sucres totaux omis car absents de la fiche d’anis.","note":"Estimation de formulation sans essai en cuisine ni analyse de laboratoire. 561 g est la somme crue, pas un poids final mesuré. Sucres totaux en attente : USDA171316 ne renseigne pas ce nutriment, sans remplacement par zéro. Marque de levure chimique, jus et rendement réel peuvent modifier les valeurs.","missing_nutrients":["sugar_g"]},"image_url":"/recetas/rollitos-de-anis/portada.webp","gallery":[{"url":"/recetas/rollitos-de-anis/portada.webp","alt":"Petits anneaux de biscuit à l’anis vert légèrement dorés, sans glaçage, sur une assiette blanche"}],"published":true,"editorial_status":"published","keywords":["biscuits à l’anis vert","anneaux à l’orange","petits pains à l’anis","anis sans liqueur"],"notes":"Formule originale proposée d’anneaux au four à l’anis vert alimentaire, à l’huile d’olive et au jus d’orange ; ni pain fermenté ni beignets frits. Œuf, lait et liqueur ne sont pas des ingrédients, mais l’absence d’allergènes ou traces n’est pas revendiquée : contient blé/gluten ; vérifiez étiquettes et contamination croisée. Utilisez Pimpinella anisum alimentaire ; badiane, fenouil et extraits ne sont pas des remplacements équivalents. Aucune équivalence de dose pour liqueurs ou huiles essentielles. Quantités, 18 pièces et texture sont proposées, sans essai en cuisine. La pâte compte 561 g d’ingrédients crus ; poids final, évaporation et pertes de manipulation ne sont pas mesurés. Utilisez toute l’huile, le jus et l’anis sans farine supplémentaire pour façonner ni sucre de finition. Modifier jus, farine, huile ou sucre change hydratation, texture et nutrition ; notez et recalculez sans promettre le même résultat. Le préchauffage coïncide avec le façonnage, et le refroidissement de la première plaque avec la cuisson de la seconde ; durée complète 105 minutes. La farine est crue : ne goûtez pas la pâte, nettoyez mains et ustensiles et cuisez le centre complètement. Lavez l’orange à l’eau courante sans savon avant de couper. Comme proposition de qualité non testée, refroidissez complètement et gardez jusqu’à 3 jours hermétiquement, au frais et au sec ; humidité et climat peuvent raccourcir ce délai. Moisissure ou humidité anormale : jetez sans goûter. Aucune durée commerciale ou congélation vérifiée. Nutrition estimée avec sept fiches USDA, formule entière divisée par 18 : seuls les nutriments présents dans toutes les fiches sont publiés. La fiche de l’anis ne renseigne pas les sucres totaux ; ils restent en attente, sans remplacement par zéro.","seo":{"title":"Anneaux à l’anis et à l’orange au four : recette","description":"Biscuits à l’anis vert, à l’orange et à l’huile : 18 pièces proposées, deux fournées et refroidissement complet. Nutrition estimée, essai en cuisine en attente.","image_alt":"Petits anneaux de biscuit à l’anis vert légèrement dorés, sans glaçage, sur une assiette blanche","image_variants":["/recetas/rollitos-de-anis/portada-1x1.webp","/recetas/rollitos-de-anis/portada-4x3.webp","/recetas/rollitos-de-anis/portada-16x9.webp"],"faq":[{"q":"Ces anneaux sont-ils du pain ou des beignets frits ?","a":"Petits anneaux cuits au four de texture biscuitée, avec agent levant chimique. Ni levure de boulanger, friture, liqueur ou glaçage. Quantités et texture sont une proposition originale en attente d’essai en cuisine."},{"q":"Peut-on remplacer l’anis vert par de la badiane ou une liqueur ?","a":"Aucune équivalence proposée. Utilisez 4 g de graines alimentaires d’anis vert et conservez toute la graine écrasée. Autres épices, liqueurs et extraits modifient goût, composition et hydratation : autre formule et nouveau calcul nécessaires."},{"q":"Pourquoi les sucres totaux manquent-ils et combien de temps les garder ?","a":"La fiche USDA de l’anis ne renseigne pas les sucres ; ni zéro ni somme incomplète ne sont inventés comme total. Les sept nutriments disponibles sont estimés pour une des 18 pièces. Proposition de qualité non testée : jusqu’à 3 jours complètement froids, hermétiques, au frais et au sec ; humidité et climat peuvent raccourcir ce délai."}]},"content_html":"<p>Petits anneaux au four de texture biscuitée, aux graines d’anis vert, à l’huile d’olive et au jus d’orange. Formule originale proposée pour 18 pièces sans liqueur, œuf ni lait ajoutés ; 105 minutes avec deux fournées et refroidissement, en attente d’essai en cuisine.</p><p>Formule originale proposée d’anneaux au four à l’anis vert alimentaire, à l’huile d’olive et au jus d’orange ; ni pain fermenté ni beignets frits. Œuf, lait et liqueur ne sont pas des ingrédients, mais l’absence d’allergènes ou traces n’est pas revendiquée : contient blé/gluten ; vérifiez étiquettes et contamination croisée. Utilisez Pimpinella anisum alimentaire ; badiane, fenouil et extraits ne sont pas des remplacements équivalents. Aucune équivalence de dose pour liqueurs ou huiles essentielles. Quantités, 18 pièces et texture sont proposées, sans essai en cuisine. La pâte compte 561 g d’ingrédients crus ; poids final, évaporation et pertes de manipulation ne sont pas mesurés. Utilisez toute l’huile, le jus et l’anis sans farine supplémentaire pour façonner ni sucre de finition. Modifier jus, farine, huile ou sucre change hydratation, texture et nutrition ; notez et recalculez sans promettre le même résultat. Le préchauffage coïncide avec le façonnage, et le refroidissement de la première plaque avec la cuisson de la seconde ; durée complète 105 minutes. La farine est crue : ne goûtez pas la pâte, nettoyez mains et ustensiles et cuisez le centre complètement. Lavez l’orange à l’eau courante sans savon avant de couper. Comme proposition de qualité non testée, refroidissez complètement et gardez jusqu’à 3 jours hermétiquement, au frais et au sec ; humidité et climat peuvent raccourcir ce délai. Moisissure ou humidité anormale : jetez sans goûter. Aucune durée commerciale ou congélation vérifiée. Nutrition estimée avec sept fiches USDA, formule entière divisée par 18 : seuls les nutriments présents dans toutes les fiches sont publiés. La fiche de l’anis ne renseigne pas les sucres totaux ; ils restent en attente, sans remplacement par zéro.</p>"},{"id":"05f8b3eb-99e9-53f5-a5a2-0d249c3914be","recipe_group_id":"f2371d66-d49e-4092-94d0-7e3e2584aa39","slug":"rotolini-all-anice","public_path":"/it/rotolini-all-anice","source_url":null,"language":"it","title":"Anellini all’anice verde e arancia al forno","excerpt":"Biscotti ad anello con anice verde, arancia e olio: quantità raggruppate, riposo, due infornate e raffreddamento completo con nutrizione USDA stimata.","summary":"Piccoli anelli al forno dalla consistenza di biscotto con anice verde, olio d’oliva e succo d’arancia. Formula originale proposta per 18 pezzi senza liquore, uova o latte aggiunti; 105 minuti con due infornate e raffreddamento, in attesa di prova in cucina.","category":"Dolci","category_slug":"postres","difficulty":"Facile","course":"Biscotti","cuisine":"Ispirazione spagnola","prep_time_minutes":25,"cook_time_minutes":40,"total_time_minutes":105,"servings":18,"ingredients":[{"name":"farina di frumento per uso comune","amount":"300","unit":"g","group":"Impasto"},{"name":"olio d’oliva","amount":"80","unit":"g","group":"Impasto"},{"name":"succo d’arancia crudo appena spremuto, senza semi","amount":"100","unit":"g","group":"Impasto"},{"name":"zucchero bianco semolato","amount":"70","unit":"g","group":"Impasto"},{"name":"semi di anice verde alimentare (Pimpinella anisum)","amount":"4","unit":"g","group":"Aroma e agente lievitante"},{"name":"lievito chimico a doppia azione","amount":"6","unit":"g","group":"Aroma e agente lievitante"},{"name":"sale fino","amount":"1","unit":"g","group":"Aroma e agente lievitante"}],"steps":[{"title":"Prepara ingredienti e teglie","content":"Prepara bilancia, ciotole, mortaio, spatola, coltello e due teglie di circa 30 × 40 cm con carta da forno, senza grasso aggiunto. Lava l’arancia sotto acqua corrente prima di tagliarla e spremila; elimina i semi e pesa 100 g di succo. Pesa separatamente 300 g di farina, 80 g di olio, 70 g di zucchero, 4 g di anice verde, 6 g di lievito chimico e 1 g di sale. Usa anice verde alimentare, non anice stellato, finocchio o liquore.","image_url":"/recetas/rollitos-de-anis/paso-01.webp","image_alt":"Anellini all’anice verde e arancia al forno: Prepara ingredienti e teglie"},{"title":"Pesta l’anice e mescola i secchi","content":"Pesta brevemente i 4 g di anice nel mortaio per rompere i semi, senza eliminare alcuna parte. Mescola in una ciotola 300 g di farina, 6 g di lievito chimico e 1 g di sale con un cucchiaio, distribuendoli bene. Questa versione usa un agente lievitante chimico, non lievito di birra. Non assaggiare farina o impasto crudi anche senza uova.","image_url":"/recetas/rollitos-de-anis/paso-02.webp","image_alt":"Anellini all’anice verde e arancia al forno: Pesta l’anice e mescola i secchi"},{"title":"Mescola succo, olio e zucchero","content":"In un’altra ciotola mescola 100 g di succo d’arancia, 80 g di olio e 70 g di zucchero. Lavora con la frusta per disperdere lo zucchero e incorpora tutto l’anice pestato. Può rimanere zucchero non sciolto e l’olio può separarsi se ti fermi: rimescola prima di unire i composti. Non aggiungere uova, latte, liquore o copertura.","image_url":"/recetas/rollitos-de-anis/paso-03.webp","image_alt":"Anellini all’anice verde e arancia al forno: Mescola succo, olio e zucchero"},{"title":"Riunisci l’impasto e fallo riposare","content":"Aggiungi i liquidi ai secchi e mescola con la spatola finché non resta farina libera. Riunisci con mani pulite, senza lavorare come pane o infarinare il piano. Copri e lascia riposare 10 minuti per idratare la farina. L’impasto deve formare un cordoncino senza sbriciolarsi; se le quantità proposte non lo consentono, registra la deviazione prima di cambiare acqua o farina e ricalcola. Accendi il forno a 180 °C, statico sopra e sotto, per circa 15 minuti di preriscaldamento mentre formi i pezzi.","image_url":"/recetas/rollitos-de-anis/paso-04.webp","image_alt":"Anellini all’anice verde e arancia al forno: Riunisci l’impasto e fallo riposare"},{"title":"Forma gli anellini","content":"Dividi tutto l’impasto in 18 porzioni il più possibile uguali, circa 31 g crudi ciascuna; il totale proposto di 561 g di ingredienti non è un peso finale misurato. Rotola ogni porzione sul piano pulito senza farina extra in un cordoncino di circa 16 cm e unisci le estremità premendole. Forma anelli di circa 6 cm di diametro esterno con foro aperto. Metti 9 pezzi su ogni teglia in tre file, distanti circa 3 cm; non cospargere di zucchero.","image_url":"/recetas/rollitos-de-anis/paso-05.webp","image_alt":"Anellini all’anice verde e arancia al forno: Forma gli anellini"},{"title":"Cuoci a turni e controlla l’interno","content":"Cuoci la prima teglia al centro a 180 °C per circa 18 minuti, finché gli anelli sono sodi, appena dorati sotto e senza centro umido quando apri un pezzo. Togli e lascia che il forno recuperi temperatura per circa 4 minuti prima della seconda teglia, da cuocere per altri 18 minuti. Il margine di cottura è 40 minuti per i due turni. Se al centro resta impasto umido, prolunga e registra il tempo; non giudicare solo dal colore e non assaggiare impasto crudo.","image_url":"/recetas/rollitos-de-anis/paso-06.webp","image_alt":"Anellini all’anice verde e arancia al forno: Cuoci a turni e controlla l’interno"},{"title":"Raffredda completamente sulla griglia","content":"Lascia ogni infornata circa 5 minuti sulla teglia, poi trasferisci sulla griglia con una spatola. Prevedi circa 30 minuti totali di raffreddamento per infornata, compresi quei 5; la prima raffredda mentre cuoce la seconda, quindi si aggiunge separatamente solo il raffreddamento finale dopo l’ultima. Lascia raffreddare completamente prima di chiudere un contenitore: piccoli anelli dalla consistenza di biscotto, non pane soffice, senza glassa o decorazioni aggiunte.","image_url":"/recetas/rollitos-de-anis/paso-07.webp","image_alt":"Anellini all’anice verde e arancia al forno: Raffredda completamente sulla griglia"},{"title":"Servi e conserva gli anelli freddi","content":"Si propongono 18 anelli; un pezzo è la porzione per la stima nutrizionale. Il piano completo somma 105 minuti: 25 di preparazione attiva, 10 di riposo, 40 di forno a turni e 30 di raffreddamento finale; il preriscaldamento coincide con la formatura. Quantità, resa e tempi attendono prova in cucina. Come proposta domestica di qualità senza test di conservazione, riponi completamente freddi in un contenitore ermetico, fresco e asciutto, fino a 3 giorni; se diventano umidi o compare muffa, scarta senza assaggiare.","image_url":"/recetas/rollitos-de-anis/portada.webp","image_alt":"Anellini all’anice verde e arancia al forno: Servi e conserva gli anelli freddi"}],"nutrition":{"calories":118.4,"protein_g":1.8,"carbs_g":17.4,"fat_g":4.7,"saturated_fat_g":0.6,"fiber_g":0.5,"sodium_mg":48.0,"estimated":true,"source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"farina di frumento per uso comune","edible_grams":300,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"calories":364,"protein_g":10.3,"carbs_g":76.3,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2.0},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"olio d’oliva","edible_grams":80,"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"calories":884,"protein_g":0.0,"carbs_g":0.0,"fat_g":100,"saturated_fat_g":13.8,"fiber_g":0.0,"sugar_g":0.0,"sodium_mg":2.0},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients"},{"ingredient":"succo d’arancia crudo appena spremuto, senza semi","edible_grams":100,"fdc_id":169098,"fdc_description":"Orange juice, raw (Includes foods for USDA's Food Distribution Program)","per_100g":{"calories":45.0,"protein_g":0.7,"carbs_g":10.4,"fat_g":0.2,"saturated_fat_g":0.024,"fiber_g":0.2,"sugar_g":8.4,"sodium_mg":1.0},"source_url":"https://fdc.nal.usda.gov/food-details/169098/nutrients"},{"ingredient":"zucchero bianco semolato","edible_grams":70,"fdc_id":169655,"fdc_description":"Sugars, granulated","per_100g":{"calories":387,"protein_g":0.0,"carbs_g":100,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.0,"sugar_g":99.8,"sodium_mg":1.0},"source_url":"https://fdc.nal.usda.gov/food-details/169655/nutrients"},{"ingredient":"semi di anice verde alimentare (Pimpinella anisum)","edible_grams":4,"fdc_id":171316,"fdc_description":"Spices, anise seed","per_100g":{"calories":337,"protein_g":17.6,"carbs_g":50.0,"fat_g":15.9,"saturated_fat_g":0.586,"fiber_g":14.6,"sodium_mg":16.0},"source_url":"https://fdc.nal.usda.gov/food-details/171316/nutrients"},{"ingredient":"lievito chimico a doppia azione","edible_grams":6,"fdc_id":172804,"fdc_description":"Leavening agents, baking powder, double-acting, straight phosphate","per_100g":{"calories":51.0,"protein_g":0.1,"carbs_g":24.1,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.2,"sugar_g":0.0,"sodium_mg":7890.0},"source_url":"https://fdc.nal.usda.gov/food-details/172804/nutrients"},{"ingredient":"sale fino","edible_grams":1,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0.0,"protein_g":0.0,"carbs_g":0.0,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.0,"sugar_g":0.0,"sodium_mg":38800.0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"}],"serving_size":"Un pezzo dei 18 proposti; peso finale non confermato","method":"Somma ogni nutriente presente nelle sette schede USDA per tutta la formula e dividi per 18. Nessuna perdita di forno o lavorazione inventata; zuccheri totali omessi perché assenti nella scheda dell’anice.","note":"Stima di formulazione senza prova in cucina o analisi di laboratorio. 561 g è la somma cruda, non il peso finale misurato. Zuccheri totali da confermare: USDA171316 non riporta il nutriente, senza sostituirlo con zero. Marca del lievito, succo e resa reale possono cambiare i valori.","missing_nutrients":["sugar_g"]},"image_url":"/recetas/rollitos-de-anis/portada.webp","gallery":[{"url":"/recetas/rollitos-de-anis/portada.webp","alt":"Piccoli anelli di biscotto all’anice verde appena dorati, senza glassa, su un piatto bianco"}],"published":true,"editorial_status":"published","keywords":["anellini all’anice","rotolini all’anice","biscotti anice e arancia","anice senza liquore"],"notes":"Proposta originale di anelli al forno con anice verde alimentare, olio d’oliva e succo d’arancia; non pane fermentato o ciambelle fritte. Uova, latte e liquore non sono ingredienti, ma non si dichiara assenza di allergeni o tracce: contiene frumento/glutine; controlla etichette e contaminazione incrociata. Usa Pimpinella anisum alimentare; anice stellato, finocchio ed estratti non sono sostituti equivalenti. Nessuna equivalenza di dose per liquori o oli essenziali. Quantità, 18 pezzi e consistenza sono proposti e attendono prova in cucina. Tutto l’impasto comprende 561 g di ingredienti crudi; peso finale, evaporazione e perdite di lavorazione non sono misurati. Usa tutto l’olio, il succo e l’anice senza farina aggiuntiva per formare né zucchero finale. Cambiare succo, farina, olio o zucchero altera idratazione, consistenza e nutrizione: registra e ricalcola senza promettere lo stesso risultato. Il preriscaldamento coincide con la formatura e il raffreddamento della prima teglia con la cottura della seconda; tempo completo 105 minuti. La farina è cruda: non assaggiare l’impasto, pulisci mani e utensili e cuoci completamente all’interno. Lava l’arancia sotto acqua corrente senza sapone prima di tagliarla. Come proposta di qualità non testata, raffredda completamente e conserva fino a 3 giorni ermeticamente, al fresco e all’asciutto; umidità e clima possono abbreviare il periodo. Muffa o umidità insolita: scarta senza assaggiare. Non è stabilita una durata commerciale o congelazione verificata. Nutrizione stimata con sette schede USDA, formula intera divisa per 18: si pubblicano solo nutrienti presenti in tutte le schede. La scheda dell’anice non riporta gli zuccheri totali; restano da confermare senza sostituzione con zero.","seo":{"title":"Anellini all’anice e arancia al forno: ricetta","description":"Biscotti all’anice verde, arancia e olio: 18 pezzi proposti, due infornate e raffreddamento completo. Nutrizione stimata e prova in cucina ancora da fare.","image_alt":"Piccoli anelli di biscotto all’anice verde appena dorati, senza glassa, su un piatto bianco","image_variants":["/recetas/rollitos-de-anis/portada-1x1.webp","/recetas/rollitos-de-anis/portada-4x3.webp","/recetas/rollitos-de-anis/portada-16x9.webp"],"faq":[{"q":"Questi anellini sono pane o ciambelle fritte?","a":"Piccoli anelli al forno dalla consistenza di biscotto, con agente lievitante chimico. Non contengono lievito di birra, frittura, liquore o glassa. Quantità e consistenza sono una proposta originale in attesa di prova in cucina."},{"q":"Posso sostituire l’anice verde con anice stellato o liquore?","a":"Non si propone equivalenza. Usa 4 g di semi di anice verde alimentare e conserva tutti i semi pestati. Altre spezie, liquori ed estratti cambiano gusto, composizione e idratazione: occorre un’altra formula e calcolo."},{"q":"Perché manca il totale degli zuccheri e quanto si conservano?","a":"La scheda USDA dell’anice non riporta zuccheri: non si inventa zero né somma incompleta come totale. I sette nutrienti disponibili sono stimati per uno dei 18 pezzi. Proposta di qualità senza test: fino a 3 giorni completamente freddi, ermetici, freschi e asciutti; umidità e clima possono abbreviare il periodo."}]},"content_html":"<p>Piccoli anelli al forno dalla consistenza di biscotto con anice verde, olio d’oliva e succo d’arancia. Formula originale proposta per 18 pezzi senza liquore, uova o latte aggiunti; 105 minuti con due infornate e raffreddamento, in attesa di prova in cucina.</p><p>Proposta originale di anelli al forno con anice verde alimentare, olio d’oliva e succo d’arancia; non pane fermentato o ciambelle fritte. Uova, latte e liquore non sono ingredienti, ma non si dichiara assenza di allergeni o tracce: contiene frumento/glutine; controlla etichette e contaminazione incrociata. Usa Pimpinella anisum alimentare; anice stellato, finocchio ed estratti non sono sostituti equivalenti. Nessuna equivalenza di dose per liquori o oli essenziali. Quantità, 18 pezzi e consistenza sono proposti e attendono prova in cucina. Tutto l’impasto comprende 561 g di ingredienti crudi; peso finale, evaporazione e perdite di lavorazione non sono misurati. Usa tutto l’olio, il succo e l’anice senza farina aggiuntiva per formare né zucchero finale. Cambiare succo, farina, olio o zucchero altera idratazione, consistenza e nutrizione: registra e ricalcola senza promettere lo stesso risultato. Il preriscaldamento coincide con la formatura e il raffreddamento della prima teglia con la cottura della seconda; tempo completo 105 minuti. La farina è cruda: non assaggiare l’impasto, pulisci mani e utensili e cuoci completamente all’interno. Lava l’arancia sotto acqua corrente senza sapone prima di tagliarla. Come proposta di qualità non testata, raffredda completamente e conserva fino a 3 giorni ermeticamente, al fresco e all’asciutto; umidità e clima possono abbreviare il periodo. Muffa o umidità insolita: scarta senza assaggiare. Non è stabilita una durata commerciale o congelazione verificata. Nutrizione stimata con sette schede USDA, formula intera divisa per 18: si pubblicano solo nutrienti presenti in tutte le schede. La scheda dell’anice non riporta gli zuccheri totali; restano da confermare senza sostituzione con zero.</p>"},{"id":"92e5b0e3-35d8-58ed-bbb5-5de30298fd39","recipe_group_id":"f2371d66-d49e-4092-94d0-7e3e2584aa39","slug":"アニスのロールクッキー","public_path":"/ja/アニスのロールクッキー","source_url":null,"language":"ja","title":"グリーンアニスとオレンジの焼きリングクッキー","excerpt":"グリーンアニス、オレンジ、オリーブオイルで作る小さなリングクッキー。材料量、休ませる時間、二回の焼成と冷却、USDAによる栄養の推定を記載。","summary":"グリーンアニスの種、オリーブオイル、オレンジ果汁を使い、クッキーの食感に焼く小さなリングです。リキュール、卵、牛乳を加えない独自の配合案で18個を想定。二回の焼成と冷却を含め105分を見込み、実際の調理試験は未実施です。","category":"デザート","category_slug":"postres","difficulty":"簡単","course":"クッキー","cuisine":"スペイン風","prep_time_minutes":25,"cook_time_minutes":40,"total_time_minutes":105,"servings":18,"ingredients":[{"name":"一般的な小麦粉（オールパーパス）","amount":"300","unit":"g","group":"生地"},{"name":"オリーブオイル","amount":"80","unit":"g","group":"生地"},{"name":"搾りたての未加熱オレンジ果汁、種を除く","amount":"100","unit":"g","group":"生地"},{"name":"白いグラニュー糖","amount":"70","unit":"g","group":"生地"},{"name":"食品用グリーンアニスの種（Pimpinella anisum）","amount":"4","unit":"g","group":"香りと膨張剤"},{"name":"ダブルアクティングのベーキングパウダー","amount":"6","unit":"g","group":"香りと膨張剤"},{"name":"細かい塩","amount":"1","unit":"g","group":"香りと膨張剤"}],"steps":[{"title":"材料と天板を準備する","content":"はかり、ボウル、乳鉢、へら、包丁と、約30 × 40 cmの天板二枚を用意します。天板にはオーブンシートを敷き、追加の油脂は塗りません。オレンジを切る前に流水で洗って搾り、種を除いて果汁100 gを量ります。別々に小麦粉300 g、油80 g、砂糖70 g、グリーンアニス4 g、ベーキングパウダー6 g、塩1 gを量ります。食品用グリーンアニスを使い、スターアニス、フェンネル、リキュールは使いません。","image_url":"/recetas/rollitos-de-anis/paso-01.webp","image_alt":"グリーンアニスとオレンジの焼きリングクッキー: 材料と天板を準備する"},{"title":"アニスを砕き、粉類を混ぜる","content":"アニス4 gを乳鉢で軽く砕いて種を割り、一部を取り除かず全部使います。ボウルに小麦粉300 g、ベーキングパウダー6 g、塩1 gを入れ、スプーンで均一に混ぜます。この配合は化学的な膨張剤を使い、パン用イーストは使いません。卵がなくても、生の粉や生地を味見しないでください。","image_url":"/recetas/rollitos-de-anis/paso-02.webp","image_alt":"グリーンアニスとオレンジの焼きリングクッキー: アニスを砕き、粉類を混ぜる"},{"title":"果汁、油、砂糖を混ぜる","content":"別のボウルにオレンジ果汁100 g、油80 g、砂糖70 gを入れます。泡立て器で砂糖を分散させ、砕いたアニスを全量加えます。砂糖が少し溶け残ることや、手を止めると油が分離することがあります。粉類と合わせる直前にもう一度混ぜます。卵、牛乳、リキュール、トッピングは加えません。","image_url":"/recetas/rollitos-de-anis/paso-03.webp","image_alt":"グリーンアニスとオレンジの焼きリングクッキー: 果汁、油、砂糖を混ぜる"},{"title":"生地をまとめて休ませる","content":"液体を粉類に加え、粉が残らなくなるまでへらで混ぜます。清潔な手でまとめ、パンのようにこねたり台に打ち粉をしたりしません。覆って10分休ませ、粉に水分をなじませます。崩れずにひも状にできる生地を目指します。提案量でまとまらない場合は、水や粉を変更する前に違いを記録し、栄養を再計算します。成形中にオーブンを上下加熱180 °Cで約15分予熱します。","image_url":"/recetas/rollitos-de-anis/paso-04.webp","image_alt":"グリーンアニスとオレンジの焼きリングクッキー: 生地をまとめて休ませる"},{"title":"小さなリングに成形する","content":"生地を全量、できるだけ均等な18個に分けます。一個の生地は約31 gを想定します。材料の合計561 gは焼き上がりを実測した重さではありません。打ち粉のない清潔な台で各生地を約16 cmのひも状にし、両端を押してつなぎます。外径約6 cmで中央の穴が開いたリングにします。各天板に9個ずつ三列に並べ、約3 cm間隔を空けます。砂糖を振りかけません。","image_url":"/recetas/rollitos-de-anis/paso-05.webp","image_alt":"グリーンアニスとオレンジの焼きリングクッキー: 小さなリングに成形する"},{"title":"順に焼き、中心まで確認する","content":"最初の天板をオーブン中央に入れ、180 °Cで約18分焼きます。リングがしっかりし、底が薄く色づき、一個を開いたとき中心に湿った生地がないことを確認します。取り出し、約4分待って庫内温度を戻してから二枚目を入れ、さらに18分焼きます。両方の焼成枠は40分です。中心に湿った生地が残る場合は延長して時間を記録します。色だけで判断せず、生地を生のまま味見しません。","image_url":"/recetas/rollitos-de-anis/paso-06.webp","image_alt":"グリーンアニスとオレンジの焼きリングクッキー: 順に焼き、中心まで確認する"},{"title":"網の上で完全に冷ます","content":"各回の焼き上がりを天板上で約5分置き、へらで網に移します。各回の冷却はその5分も含め約30分を見込みます。最初の分は二回目の焼成中に冷めるので、最後の焼成後の冷却だけを別に加算します。容器を閉じる前に完全に冷ましてください。ふんわりしたパンではなく、クッキーの食感の小さなリングにし、アイシングや飾りは加えません。","image_url":"/recetas/rollitos-de-anis/paso-07.webp","image_alt":"グリーンアニスとオレンジの焼きリングクッキー: 網の上で完全に冷ます"},{"title":"冷めてから提供し、保存する","content":"18個を提案量とし、栄養の推定は一個分です。全体は105分で、実作業25分、休ませる10分、二回の焼成40分、最後の冷却30分を含みます。予熱は成形と並行します。量、出来上がり、時間は調理試験による確認待ちです。保存試験のない家庭向け品質の目安として、完全に冷ましたものを密閉し、涼しく乾いた場所で最長3日保存する案です。湿ったりカビが出たりしたら、味見せず捨てます。","image_url":"/recetas/rollitos-de-anis/portada.webp","image_alt":"グリーンアニスとオレンジの焼きリングクッキー: 冷めてから提供し、保存する"}],"nutrition":{"calories":118.4,"protein_g":1.8,"carbs_g":17.4,"fat_g":4.7,"saturated_fat_g":0.6,"fiber_g":0.5,"sodium_mg":48.0,"estimated":true,"source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"一般的な小麦粉（オールパーパス）","edible_grams":300,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"calories":364,"protein_g":10.3,"carbs_g":76.3,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2.0},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"オリーブオイル","edible_grams":80,"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"calories":884,"protein_g":0.0,"carbs_g":0.0,"fat_g":100,"saturated_fat_g":13.8,"fiber_g":0.0,"sugar_g":0.0,"sodium_mg":2.0},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients"},{"ingredient":"搾りたての未加熱オレンジ果汁、種を除く","edible_grams":100,"fdc_id":169098,"fdc_description":"Orange juice, raw (Includes foods for USDA's Food Distribution Program)","per_100g":{"calories":45.0,"protein_g":0.7,"carbs_g":10.4,"fat_g":0.2,"saturated_fat_g":0.024,"fiber_g":0.2,"sugar_g":8.4,"sodium_mg":1.0},"source_url":"https://fdc.nal.usda.gov/food-details/169098/nutrients"},{"ingredient":"白いグラニュー糖","edible_grams":70,"fdc_id":169655,"fdc_description":"Sugars, granulated","per_100g":{"calories":387,"protein_g":0.0,"carbs_g":100,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.0,"sugar_g":99.8,"sodium_mg":1.0},"source_url":"https://fdc.nal.usda.gov/food-details/169655/nutrients"},{"ingredient":"食品用グリーンアニスの種（Pimpinella anisum）","edible_grams":4,"fdc_id":171316,"fdc_description":"Spices, anise seed","per_100g":{"calories":337,"protein_g":17.6,"carbs_g":50.0,"fat_g":15.9,"saturated_fat_g":0.586,"fiber_g":14.6,"sodium_mg":16.0},"source_url":"https://fdc.nal.usda.gov/food-details/171316/nutrients"},{"ingredient":"ダブルアクティングのベーキングパウダー","edible_grams":6,"fdc_id":172804,"fdc_description":"Leavening agents, baking powder, double-acting, straight phosphate","per_100g":{"calories":51.0,"protein_g":0.1,"carbs_g":24.1,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.2,"sugar_g":0.0,"sodium_mg":7890.0},"source_url":"https://fdc.nal.usda.gov/food-details/172804/nutrients"},{"ingredient":"細かい塩","edible_grams":1,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0.0,"protein_g":0.0,"carbs_g":0.0,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.0,"sugar_g":0.0,"sodium_mg":38800.0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"}],"serving_size":"提案した18個のうち一個。完成重量は未確認","method":"七件のUSDAデータすべてに記載がある栄養素について配合全量の値を合計し、18で割ります。焼成や成形の損失を作らず、アニスに記載のない糖類総量は省略します。","note":"調理試験や分析をしていない配合上の推定。561 gは生材料の合計で、完成重量の実測ではありません。USDA171316に糖類の記載がないため総量は確認待ちとし、ゼロで置き換えません。膨張剤の銘柄、果汁、実際の出来上がりで値は変わります。","missing_nutrients":["sugar_g"]},"image_url":"/recetas/rollitos-de-anis/portada.webp","gallery":[{"url":"/recetas/rollitos-de-anis/portada.webp","alt":"白い皿に並ぶ、アイシングのない薄い黄金色の小さなグリーンアニスのリングクッキー"}],"published":true,"editorial_status":"published","keywords":["アニスクッキー","オレンジのリングクッキー","グリーンアニス","リキュールなし"],"notes":"食品用グリーンアニス、オリーブオイル、オレンジ果汁で作る焼きリングの独自配合案です。発酵パンや揚げドーナツではありません。卵、牛乳、リキュールは材料に含めませんが、アレルゲンや微量混入がないとは主張しません。小麦・グルテンを含み、表示と交差接触を確認してください。食品用Pimpinella anisumを使います。スターアニス、フェンネル、抽出物は同等の代用品ではなく、リキュールや精油の換算量も提示しません。量、18個という出来上がり、食感は提案で、調理試験は未実施です。生材料の合計は561 gであり、完成重量、蒸発量、成形時の損失は実測していません。油、果汁、アニスは全量使い、成形の打ち粉や仕上げの砂糖を加えません。果汁、粉、油、砂糖を変えると水分、食感、栄養が変わります。記録して再計算し、同じ結果を約束しません。予熱は成形と、一回目の冷却は二回目の焼成と並行し、全体105分です。粉は生の食品です。生地を味見せず、手や器具を清潔にし、中心まで焼きます。オレンジは切る前にせっけんを使わず流水で洗います。試験のない品質の目安として、完全に冷まして密閉し、涼しく乾いた場所で最長3日保存する案です。湿度や気候によって短くなる場合があります。カビや異常な湿りがあれば味見せず捨てます。商用の保存期限や冷凍期間を検証したものではありません。七件のUSDAデータを使い、配合全量を18で割った栄養の推定です。全データに記載のある栄養素だけを掲載します。アニスのデータには糖類総量の記載がないため、その値は確認待ちとし、ゼロで置き換えません。","seo":{"title":"アニスとオレンジの焼きリングクッキーの作り方","description":"グリーンアニス、オレンジ、油の小さな焼きクッキー。18個の配合案、二回の焼成と冷却を含む時間、栄養の推定を掲載。調理試験は未実施。","image_alt":"白い皿に並ぶ、アイシングのない薄い黄金色の小さなグリーンアニスのリングクッキー","image_variants":["/recetas/rollitos-de-anis/portada-1x1.webp","/recetas/rollitos-de-anis/portada-4x3.webp","/recetas/rollitos-de-anis/portada-16x9.webp"],"faq":[{"q":"これはパンや揚げドーナツですか。","a":"化学的な膨張剤を使い、クッキーの食感に焼く小さなリングです。パン用イースト、揚げ工程、リキュール、アイシングは使いません。量と食感は独自の提案で、調理試験による確認待ちです。"},{"q":"グリーンアニスをスターアニスやリキュールに置き換えられますか。","a":"同等の換算は提案しません。食品用グリーンアニスの種4 gを使い、砕いた種を全量残します。別のスパイス、リキュール、抽出物は味、成分、水分を変えるため、別の配合と計算が必要です。"},{"q":"糖類総量がない理由と保存期間は。","a":"USDAのアニスデータには糖類の記載がありません。ゼロや不完全な合計を総量として作りません。掲載する七つの栄養素は18個のうち一個当たりの推定です。未検証の品質の目安は、完全に冷まし密閉して涼しく乾いた場所で最長3日。湿度や気候で短くなる場合があります。"}]},"content_html":"<p>グリーンアニスの種、オリーブオイル、オレンジ果汁を使い、クッキーの食感に焼く小さなリングです。リキュール、卵、牛乳を加えない独自の配合案で18個を想定。二回の焼成と冷却を含め105分を見込み、実際の調理試験は未実施です。</p><p>食品用グリーンアニス、オリーブオイル、オレンジ果汁で作る焼きリングの独自配合案です。発酵パンや揚げドーナツではありません。卵、牛乳、リキュールは材料に含めませんが、アレルゲンや微量混入がないとは主張しません。小麦・グルテンを含み、表示と交差接触を確認してください。食品用Pimpinella anisumを使います。スターアニス、フェンネル、抽出物は同等の代用品ではなく、リキュールや精油の換算量も提示しません。量、18個という出来上がり、食感は提案で、調理試験は未実施です。生材料の合計は561 gであり、完成重量、蒸発量、成形時の損失は実測していません。油、果汁、アニスは全量使い、成形の打ち粉や仕上げの砂糖を加えません。果汁、粉、油、砂糖を変えると水分、食感、栄養が変わります。記録して再計算し、同じ結果を約束しません。予熱は成形と、一回目の冷却は二回目の焼成と並行し、全体105分です。粉は生の食品です。生地を味見せず、手や器具を清潔にし、中心まで焼きます。オレンジは切る前にせっけんを使わず流水で洗います。試験のない品質の目安として、完全に冷まして密閉し、涼しく乾いた場所で最長3日保存する案です。湿度や気候によって短くなる場合があります。カビや異常な湿りがあれば味見せず捨てます。商用の保存期限や冷凍期間を検証したものではありません。七件のUSDAデータを使い、配合全量を18で割った栄養の推定です。全データに記載のある栄養素だけを掲載します。アニスのデータには糖類総量の記載がないため、その値は確認待ちとし、ゼロで置き換えません。</p>"},{"id":"872826f0-25fb-5fa2-b57f-c0fdee940a88","recipe_group_id":"f2371d66-d49e-4092-94d0-7e3e2584aa39","slug":"rolinhos-de-anis","public_path":"/pt/rolinhos-de-anis","source_url":null,"language":"pt","title":"Rolinhos de anis-verde e laranja assados","excerpt":"Biscoitos em argola com anis-verde, laranja e azeite: quantidades agrupadas, descanso, duas fornadas e resfriamento completo com nutrição USDA estimada.","summary":"Pequenas argolas assadas com textura de biscoito, sementes de anis-verde, azeite e suco de laranja. Fórmula original proposta para 18 unidades, sem licor, ovo ou leite adicionados; 105 minutos com duas fornadas e resfriamento, pendentes de teste na cozinha.","category":"Sobremesas","category_slug":"postres","difficulty":"Fácil","course":"Biscoitos","cuisine":"Inspiração espanhola","prep_time_minutes":25,"cook_time_minutes":40,"total_time_minutes":105,"servings":18,"ingredients":[{"name":"farinha de trigo de uso comum","amount":"300","unit":"g","group":"Massa"},{"name":"azeite de oliva","amount":"80","unit":"g","group":"Massa"},{"name":"suco de laranja cru, espremido na hora e sem sementes","amount":"100","unit":"g","group":"Massa"},{"name":"açúcar branco granulado","amount":"70","unit":"g","group":"Massa"},{"name":"sementes de anis-verde próprias para alimentos (Pimpinella anisum)","amount":"4","unit":"g","group":"Aroma e fermento"},{"name":"fermento químico de dupla ação","amount":"6","unit":"g","group":"Aroma e fermento"},{"name":"sal fino","amount":"1","unit":"g","group":"Aroma e fermento"}],"steps":[{"title":"Prepare ingredientes e assadeiras","content":"Separe balança, tigelas, pilão, espátula, faca e duas assadeiras de cerca de 30 × 40 cm com papel próprio para forno, sem gordura extra. Lave a laranja em água corrente antes de cortar e esprema; retire sementes e pese 100 g de suco. Pese separadamente 300 g de farinha, 80 g de azeite, 70 g de açúcar, 4 g de anis-verde, 6 g de fermento químico e 1 g de sal. Use anis-verde próprio para alimentos, não anis-estrelado, funcho ou licor.","image_url":"/recetas/rollitos-de-anis/paso-01.webp","image_alt":"Rolinhos de anis-verde e laranja assados: Prepare ingredientes e assadeiras"},{"title":"Triture o anis e misture os secos","content":"Triture brevemente os 4 g de anis no pilão para quebrar as sementes, sem descartar nenhuma parte. Misture em uma tigela os 300 g de farinha, os 6 g de fermento químico e o 1 g de sal, distribuindo bem com uma colher. Esta versão usa fermento químico, não fermento biológico. Não prove farinha ou massa cruas, mesmo sem ovo.","image_url":"/recetas/rollitos-de-anis/paso-02.webp","image_alt":"Rolinhos de anis-verde e laranja assados: Triture o anis e misture os secos"},{"title":"Misture suco, azeite e açúcar","content":"Em outra tigela, misture os 100 g de suco de laranja, os 80 g de azeite e os 70 g de açúcar. Mexa com um batedor para dispersar o açúcar e acrescente todo o anis triturado. Pode restar açúcar sem dissolver e o azeite pode se separar ao parar: mexa novamente antes de juntar as misturas. Não acrescente ovo, leite, licor ou cobertura.","image_url":"/recetas/rollitos-de-anis/paso-03.webp","image_alt":"Rolinhos de anis-verde e laranja assados: Misture suco, azeite e açúcar"},{"title":"Junte a massa e deixe descansar","content":"Acrescente os líquidos aos secos e misture com espátula até não restar farinha solta. Junte com mãos limpas, sem sovar como pão nem enfarinhar a bancada. Cubra e descanse 10 minutos para hidratar a farinha. A massa deve formar um cordão sem esfarelar; se as quantidades propostas não permitirem isso, registre a diferença antes de mudar água ou farinha e recalcule. Ligue o forno a 180 °C, com calor superior e inferior, para preaquecer cerca de 15 minutos enquanto modela.","image_url":"/recetas/rollitos-de-anis/paso-04.webp","image_alt":"Rolinhos de anis-verde e laranja assados: Junte a massa e deixe descansar"},{"title":"Modele pequenas argolas","content":"Divida toda a massa em 18 porções tão iguais quanto possível, cerca de 31 g crus por unidade; os 561 g de ingredientes propostos não são peso final medido. Role cada porção sobre superfície limpa sem farinha extra em um cordão de cerca de 16 cm e una as pontas pressionando. Forme argolas com cerca de 6 cm de diâmetro externo e furo aberto. Coloque 9 em cada assadeira em três fileiras, separadas por cerca de 3 cm; não polvilhe açúcar.","image_url":"/recetas/rollitos-de-anis/paso-05.webp","image_alt":"Rolinhos de anis-verde e laranja assados: Modele pequenas argolas"},{"title":"Asse por fornadas e confira o centro","content":"Asse a primeira assadeira na parte central a 180 °C por cerca de 18 minutos, até as argolas ficarem firmes, levemente douradas por baixo e sem centro úmido ao abrir uma unidade. Retire e deixe o forno recuperar a temperatura por cerca de 4 minutos antes da segunda assadeira, por mais 18 minutos. Reserve 40 minutos para as duas fornadas. Se o centro mantiver massa úmida, prolongue e registre o tempo; não avalie só pela cor nem prove massa crua.","image_url":"/recetas/rollitos-de-anis/paso-06.webp","image_alt":"Rolinhos de anis-verde e laranja assados: Asse por fornadas e confira o centro"},{"title":"Esfrie completamente sobre uma grade","content":"Deixe cada fornada cerca de 5 minutos na assadeira e transfira para uma grade com espátula. Reserve cerca de 30 minutos de resfriamento total por fornada, incluindo esses 5; a primeira esfria enquanto a segunda assa, então só some separadamente o resfriamento final depois da última. Espere esfriar completamente antes de fechar um recipiente: pequenas argolas de textura de biscoito, não pão fofo, sem glacê ou decoração extra.","image_url":"/recetas/rollitos-de-anis/paso-07.webp","image_alt":"Rolinhos de anis-verde e laranja assados: Esfrie completamente sobre uma grade"},{"title":"Sirva e guarde os rolinhos frios","content":"São propostas 18 unidades; uma é a porção usada para estimar a nutrição. O plano completo soma 105 minutos: 25 de preparo ativo, 10 de descanso, 40 de forno por fornadas e 30 de resfriamento final; o preaquecimento ocorre durante a modelagem. Quantidades, rendimento e tempos aguardam teste na cozinha. Como proposta doméstica de qualidade sem teste de conservação, guarde completamente frios em recipiente hermético, em lugar fresco e seco, por até 3 dias; se ficarem úmidos ou aparecer mofo, descarte sem provar.","image_url":"/recetas/rollitos-de-anis/portada.webp","image_alt":"Rolinhos de anis-verde e laranja assados: Sirva e guarde os rolinhos frios"}],"nutrition":{"calories":118.4,"protein_g":1.8,"carbs_g":17.4,"fat_g":4.7,"saturated_fat_g":0.6,"fiber_g":0.5,"sodium_mg":48.0,"estimated":true,"source":"USDA FoodData Central — SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"farinha de trigo de uso comum","edible_grams":300,"fdc_id":168936,"fdc_description":"Wheat flour, white, all-purpose, enriched, unbleached","per_100g":{"calories":364,"protein_g":10.3,"carbs_g":76.3,"fat_g":0.98,"saturated_fat_g":0.155,"fiber_g":2.7,"sugar_g":0.27,"sodium_mg":2.0},"source_url":"https://fdc.nal.usda.gov/food-details/168936/nutrients"},{"ingredient":"azeite de oliva","edible_grams":80,"fdc_id":171413,"fdc_description":"Oil, olive, salad or cooking","per_100g":{"calories":884,"protein_g":0.0,"carbs_g":0.0,"fat_g":100,"saturated_fat_g":13.8,"fiber_g":0.0,"sugar_g":0.0,"sodium_mg":2.0},"source_url":"https://fdc.nal.usda.gov/food-details/171413/nutrients"},{"ingredient":"suco de laranja cru, espremido na hora e sem sementes","edible_grams":100,"fdc_id":169098,"fdc_description":"Orange juice, raw (Includes foods for USDA's Food Distribution Program)","per_100g":{"calories":45.0,"protein_g":0.7,"carbs_g":10.4,"fat_g":0.2,"saturated_fat_g":0.024,"fiber_g":0.2,"sugar_g":8.4,"sodium_mg":1.0},"source_url":"https://fdc.nal.usda.gov/food-details/169098/nutrients"},{"ingredient":"açúcar branco granulado","edible_grams":70,"fdc_id":169655,"fdc_description":"Sugars, granulated","per_100g":{"calories":387,"protein_g":0.0,"carbs_g":100,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.0,"sugar_g":99.8,"sodium_mg":1.0},"source_url":"https://fdc.nal.usda.gov/food-details/169655/nutrients"},{"ingredient":"sementes de anis-verde próprias para alimentos (Pimpinella anisum)","edible_grams":4,"fdc_id":171316,"fdc_description":"Spices, anise seed","per_100g":{"calories":337,"protein_g":17.6,"carbs_g":50.0,"fat_g":15.9,"saturated_fat_g":0.586,"fiber_g":14.6,"sodium_mg":16.0},"source_url":"https://fdc.nal.usda.gov/food-details/171316/nutrients"},{"ingredient":"fermento químico de dupla ação","edible_grams":6,"fdc_id":172804,"fdc_description":"Leavening agents, baking powder, double-acting, straight phosphate","per_100g":{"calories":51.0,"protein_g":0.1,"carbs_g":24.1,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.2,"sugar_g":0.0,"sodium_mg":7890.0},"source_url":"https://fdc.nal.usda.gov/food-details/172804/nutrients"},{"ingredient":"sal fino","edible_grams":1,"fdc_id":173468,"fdc_description":"Salt, table","per_100g":{"calories":0.0,"protein_g":0.0,"carbs_g":0.0,"fat_g":0.0,"saturated_fat_g":0.0,"fiber_g":0.0,"sugar_g":0.0,"sodium_mg":38800.0},"source_url":"https://fdc.nal.usda.gov/food-details/173468/nutrients"}],"serving_size":"Uma das 18 unidades propostas; peso final não confirmado","method":"Some cada nutriente presente nas sete fichas USDA para a fórmula inteira e divida por 18. Sem perdas inventadas de forno ou manuseio; açúcares totais omitidos por ausência na ficha do anis.","note":"Estimativa de formulação sem teste na cozinha ou análise de laboratório. 561 g é a soma crua, não peso final medido. Açúcares totais pendentes: USDA171316 não informa esse nutriente, sem substituir por zero. Marca do fermento, suco e rendimento real podem mudar os valores.","missing_nutrients":["sugar_g"]},"image_url":"/recetas/rollitos-de-anis/portada.webp","gallery":[{"url":"/recetas/rollitos-de-anis/portada.webp","alt":"Pequenas argolas de biscoito de anis-verde levemente douradas, sem glacê, em um prato branco"}],"published":true,"editorial_status":"published","keywords":["rolinhos de anis","biscoitos de anis-verde","rosquinhas assadas com laranja","anis sem licor"],"notes":"Proposta original de argolas assadas com anis-verde próprio para alimentos, azeite e suco de laranja; não são pão fermentado nem rosquinhas fritas. Ovo, leite e licor não são ingredientes, mas não se afirma ausência de alérgenos ou traços: contém trigo/glúten; confira rótulos e contato cruzado. Use Pimpinella anisum de uso alimentar; anis-estrelado, funcho e extratos não são substituições equivalentes. Não há equivalência de dose para licores ou óleos essenciais. Quantidades, 18 unidades e textura são propostas pendentes de teste na cozinha. A massa toda soma 561 g de ingredientes crus; peso final, evaporação e perdas de manuseio não foram medidos. Use todo o azeite, suco e anis sem farinha extra para modelar nem açúcar para finalizar. Trocar suco, farinha, azeite ou açúcar muda hidratação, textura e nutrição: registre e recalcule sem prometer o mesmo resultado. O preaquecimento ocorre durante a modelagem e a primeira fornada esfria enquanto a segunda assa; o tempo completo é 105 minutos. Farinha é alimento cru: não prove massa, limpe mãos e utensílios e asse até cozinhar por dentro. Lave a laranja em água corrente sem sabão antes de cortar. Como proposta de qualidade não testada, esfrie completamente e guarde hermeticamente, em local fresco e seco, por até 3 dias; umidade e clima podem reduzir o prazo. Mofo ou umidade anormal: descarte sem provar. Não se estabelece validade comercial ou congelamento verificado. Nutrição estimada com sete fichas USDA, fórmula inteira dividida por 18: publique apenas nutrientes presentes em todas as fichas. A ficha de anis não informa açúcares totais; esse dado fica pendente sem ser substituído por zero.","seo":{"title":"Rolinhos de anis e laranja no forno: receita","description":"Biscoitos em argola com anis-verde, laranja e azeite: 18 unidades propostas, duas fornadas, resfriamento completo e nutrição estimada. Teste na cozinha pendente.","image_alt":"Pequenas argolas de biscoito de anis-verde levemente douradas, sem glacê, em um prato branco","image_variants":["/recetas/rollitos-de-anis/portada-1x1.webp","/recetas/rollitos-de-anis/portada-4x3.webp","/recetas/rollitos-de-anis/portada-16x9.webp"],"faq":[{"q":"Esses rolinhos são pão ou rosquinhas fritas?","a":"São pequenas argolas assadas com textura de biscoito e fermento químico. Sem fermento biológico, fritura, licor ou glacê. Quantidades e textura são uma proposta original pendente de teste na cozinha."},{"q":"Posso trocar anis-verde por anis-estrelado ou licor?","a":"Não se propõe equivalência. Use 4 g de sementes de anis-verde próprias para alimentos e retenha todas as sementes trituradas. Outras especiarias, licores e extratos mudam sabor, composição e hidratação e exigem outra fórmula e cálculo."},{"q":"Por que não há açúcares totais e por quanto tempo guardar?","a":"A ficha USDA do anis não informa açúcares: não se inventa zero nem uma soma incompleta como total. Os sete nutrientes disponíveis são estimados para uma das 18 unidades. Proposta de qualidade não testada: até 3 dias completamente frios, herméticos, frescos e secos; umidade e clima podem reduzir o prazo."}]},"content_html":"<p>Pequenas argolas assadas com textura de biscoito, sementes de anis-verde, azeite e suco de laranja. Fórmula original proposta para 18 unidades, sem licor, ovo ou leite adicionados; 105 minutos com duas fornadas e resfriamento, pendentes de teste na cozinha.</p><p>Proposta original de argolas assadas com anis-verde próprio para alimentos, azeite e suco de laranja; não são pão fermentado nem rosquinhas fritas. Ovo, leite e licor não são ingredientes, mas não se afirma ausência de alérgenos ou traços: contém trigo/glúten; confira rótulos e contato cruzado. Use Pimpinella anisum de uso alimentar; anis-estrelado, funcho e extratos não são substituições equivalentes. Não há equivalência de dose para licores ou óleos essenciais. Quantidades, 18 unidades e textura são propostas pendentes de teste na cozinha. A massa toda soma 561 g de ingredientes crus; peso final, evaporação e perdas de manuseio não foram medidos. Use todo o azeite, suco e anis sem farinha extra para modelar nem açúcar para finalizar. Trocar suco, farinha, azeite ou açúcar muda hidratação, textura e nutrição: registre e recalcule sem prometer o mesmo resultado. O preaquecimento ocorre durante a modelagem e a primeira fornada esfria enquanto a segunda assa; o tempo completo é 105 minutos. Farinha é alimento cru: não prove massa, limpe mãos e utensílios e asse até cozinhar por dentro. Lave a laranja em água corrente sem sabão antes de cortar. Como proposta de qualidade não testada, esfrie completamente e guarde hermeticamente, em local fresco e seco, por até 3 dias; umidade e clima podem reduzir o prazo. Mofo ou umidade anormal: descarte sem provar. Não se estabelece validade comercial ou congelamento verificado. Nutrição estimada com sete fichas USDA, fórmula inteira dividida por 18: publique apenas nutrientes presentes em todas as fichas. A ficha de anis não informa açúcares totais; esse dado fica pendente sem ser substituído por zero.</p>"}]$records$::jsonb;
 b constant jsonb := $before${"id":"75a42c9e-6fe6-474f-8657-dde10e3f96c1","recipe_group_id":"f2371d66-d49e-4092-94d0-7e3e2584aa39","slug":"rollitos-de-anis","public_path":"/rollitos-de-anis","source_url":"https://manualdecocina.com/rollitos-de-anis/","created_at":"2026-09-23 20:50:29.843053+00","published_at":"2026-09-23 20:50:29.843053+00","expected_row_md5":"dd04eb37a8a376d5c3701c2723c1e06c"}$before$::jsonb;
 g constant uuid := 'f2371d66-d49e-4092-94d0-7e3e2584aa39';
